package dev.opencode.remote.domain

import kotlinx.serialization.Serializable

[CREDENTIAL-RELATED LINE OMITTED]
@Serializable
data class ServerProfile(
    val id: String,
    val name: String,
    val baseUrl: String,
    val username: String = "opencode",
    val defaultDirectory: String? = null,
    val serverVersion: String? = null,
    val lastUsedAt: Long = 0,
)

/** Result of GET /global/health (S2). */
@Serializable
data class ServerHealth(
    val healthy: Boolean,
    val version: String,
)

/** Connection state machine for a profile. */
sealed interface ConnectionState {
    data object Disconnected : ConnectionState
    data object Connecting : ConnectionState
    data class Connected(val health: ServerHealth) : ConnectionState
    data class Failed(val reason: String) : ConnectionState
}

package dev.opencode.remote.domain

import kotlinx.coroutines.flow.Flow

/** App settings, DataStore-backed (X1, doc 13 — v1 schema; groups grow without migration breaks). */
data class AppSettings(
    // Connection (S3)
    val connectTimeoutMs: Long = 15_000,
    val readTimeoutMs: Long = 60_000,
    val sseBackoffBaseMs: Long = 1_000,
    val sseBackoffMaxMs: Long = 30_000,
    // Sessions (C2)
    val defaultTemporary: Boolean = false,
    val tempAutoPurgeDays: Int = 7,
    val confirmDelete: Boolean = true,
    // Chat (H1/H3/H5)
    val websearchDefaultOn: Boolean = true,
