fun AgentChipsRow(
    agents: List<AgentInfo>,
    selected: String,
    onSelect: (String) -> Unit,
) {
    val native = listOf("plan", "ask", "build")
    val ordered = (native.filter { n -> agents.any { it.name == n } || true } +
        agents.map { it.name }.filter { it !in native }).distinct()
