package dev.opencode.remote.chat

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import com.mikepenz.markdown.code.highlightedCodeFence
import com.mikepenz.markdown.m3.Markdown
import com.mikepenz.markdown.m3.markdownComponents
import com.mikepenz.markdown.model.rememberStreamingMarkdownState

/**
 * Agent text renderer (P2): full markdown (tables, lists, links, GFM alerts) +
 * highlighted code fences with language header + copy button (spec §3).
 */
@Composable
fun MarkdownText(text: String, modifier: Modifier = Modifier) {
    val components = remember {
        markdownComponents(
            codeFence = highlightedCodeFence,
        )
    }
    Markdown(
        content = text,
        components = components,
        modifier = modifier,
    )
}

/** Streaming variant: appends chunks, re-parses only the unstable tail. */
@Composable
fun StreamingMarkdownText(chunks: List<String>, modifier: Modifier = Modifier) {
    val state = rememberStreamingMarkdownState()
    androidx.compose.runtime.LaunchedEffect(chunks) {
        // Re-feed on new chunk lists (simplest correct; tail re-parse is internal).
        state.clear()
        chunks.forEach { state.append(it) }
    }
    Markdown(
        markdownState = state,
        modifier = modifier,
    )
}

