// cdp-hub: one-shot CLI over the opencode browser bridge hub WS.
// Usage: bun cdp-hub.ts <browser> <method> '<json-params>'
// Example: bun cdp-hub.ts nuc-primary tabs '{}'
const HUB = process.env.CDP_HUB || "ws://127.0.0.1:9225/hub";
const [browser, method, paramsJson] = process.argv.slice(2);
if (!browser || !method) {
  console.error("usage: bun cdp-hub.ts <browser> <method> '<json>'");
  process.exit(2);
}
const params = JSON.parse(paramsJson || "{}");
const ws = new WebSocket(HUB);
let id = 0;
const timer = setTimeout(() => { console.error("hub connect timeout"); process.exit(1); }, 15000);
ws.onopen = () => {
  clearTimeout(timer);
  ws.send(JSON.stringify({ id: ++id, to: browser, method, params }));
  setTimeout(() => { console.error("hub call timeout"); process.exit(1); }, 1000 * 60 * 5);
};
ws.onmessage = (ev: any) => {
  let m: any;
  try { m = JSON.parse(String(ev.data)); } catch { return; }
  if (m.id !== undefined) {
    if (m.error) { console.error("HUB-ERROR: " + m.error); process.exit(1); }
    const r = m.result;
    console.log(typeof r === "string" ? r : JSON.stringify(r, null, 1).slice(0, 12000));
    process.exit(0);
  }
};
ws.onerror = () => { console.error("hub unreachable"); process.exit(1); };

