  ws.addEventListener("message", h);
  ws.send(JSON.stringify({ id: i, ...m }));
});
await send({ method: "Emulation.setDeviceMetricsOverride", params: { width: 360, height: 700, deviceScaleFactor: 1, mobile: false } });
