await send({ method: "Runtime.evaluate", params: { expression: "document.querySelector('#hist-btn').click()", awaitPromise: true } });
await new Promise(r => setTimeout(r, 1500));
const shot = await send({ method: "Page.captureScreenshot", params: { format: "png" } });
require("fs").writeFileSync("/tmp/hv2.png", Buffer.from(shot.data, "base64"));
console.log("saved hv2");
await send({ method: "Emulation.clearDeviceMetricsOverride", params: {} });
ws.close();
EOF
