    loadHist();
    refreshMeter();
  };
  const acts = document.createElement("span");
  acts.className = "sess-acts";
  const rn = document.createElement("button");
  rn.textContent = "✎";
  rn.title = "Rename";
  rn.dataset.tip = "Rename chat";
  rn.onclick = (e) => {
    e.stopPropagation();
    const rt = b.querySelector(".rt");
    if (!rt || b.querySelector(".sess-rename")) return;
    const inp = document.createElement("input");
    inp.className = "sess-rename";
    inp.value = s.title || s.slug || "";
    let done = false;
    const commit = async (save) => {
      if (done) return;
      done = true;
      const v = inp.value.trim();
      if (save && v && v !== (s.title || "")) {
        try {
          await api(`/session/${s.id}`, { method: "PATCH",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ title: v }) });
          s.title = v;
        } catch (err) { toast(`Rename failed: ${err.message}`); }
      }
      loadHist();
    };
    inp.onkeydown = (ev) => {
      ev.stopPropagation();
      if (ev.key === "Enter") commit(true);
      if (ev.key === "Escape") commit(false);
    };
    inp.onblur = () => commit(true);
    rt.replaceWith(inp);
    inp.focus();
    inp.select();
  };
  const del = document.createElement("button");
  del.textContent = "🗑";
  del.title = "Delete";
  del.dataset.tip = "Delete chat";
  del.classList.add("danger");
  let armed = null;
  del.onclick = async (e) => {
    e.stopPropagation();
    if (!del.classList.contains("armed")) {
      del.classList.add("armed");
      del.textContent = "?";
      clearTimeout(armed);
      armed = setTimeout(() => { del.classList.remove("armed"); del.textContent = "🗑"; }, 3000);
      return;
    }
    clearTimeout(armed);
    try {
      await api(`/session/${s.id}`, { method: "DELETE" });
      const cur = await store.get();
      if (cur.session === s.id) {
        await store.set({ session: "" });
        $("msgs").innerHTML = "";
      }
