 .addCapability(NET_CAPABILITY_INTERNET)
 .addCapability(NET_CAPABILITY_NOT_METERED)
 .build()

val jobInfo = JobInfo.Builder(jobId,
 ComponentName(mContext, CustomTransferService::class.java))
 // ...
 .setUserInitiated(true)
