 // ...
 .build(); 
4.   While the job is being executed, call [`setNotification()`](https://developer.android.com/reference/android/app/job/JobService#setNotification(android.app.job.JobParameters,%20int,%20android.app.Notification,%20int)) on the `JobService` object. Calling `setNotification()` makes the user aware that the job is running, both in the Task Manager and in the status bar notification area.

When execution is complete, call `jobFinished()` to signal to the system that the job is complete, or that the job should be rescheduled.

class CustomTransferService: JobService() {
 private val scope = CoroutineScope(Dispatchers.IO)

 @RequiresApi(Build.VERSION_CODES.UPSIDE_DOWN_CAKE)
 override fun onStartJob(params: JobParameters): Boolean {
 val notification = Notification.Builder(applicationContext,
 NOTIFICATION_CHANNEL_ID)
 .setContentTitle("My user-initiated data transfer job")
 .setSmallIcon(android.R.mipmap.myicon)
 .setContentText("Job is running")
 .build()

 setNotification(params, notification.id, notification,
 JobService.JOB_END_NOTIFICATION_POLICY_DETACH)
 // Execute the work associated with this job asynchronously.
 scope.launch {
 doDownload(params)
 }
 return true
 }

 private suspend fun doDownload(params: JobParameters) {
 // Run the relevant async download task, then call
 // jobFinished once the task is completed.
 jobFinished(params, false)
 }

 // Called when the system stops the job.
 override fun onStopJob(params: JobParameters?): Boolean {
 // Asynchronously record job-related data, such as the
 // stop reason.
 return true // or return false if job should end entirely
 }
}class CustomTransferService extends JobService{
 @RequiresApi(Build.VERSION_CODES.UPSIDE_DOWN_CAKE)
 @Override
 public boolean onStartJob(JobParameters params) {
 Notification notification = Notification.Builder(getBaseContext(),
 NOTIFICATION_CHANNEL_ID)
 .setContentTitle("My user-initiated data transfer job")
 .setSmallIcon(android.R.mipmap.myicon)
 .setContentText("Job is running")
 .build();

 setNotification(params, notification.id, notification,
 JobService.JOB_END_NOTIFICATION_POLICY_DETACH)
 // Execute the work associated with this job asynchronously.
 new Thread(() -> doDownload(params)).start();
 return true;
 }

 private void doDownload(JobParameters params) {
 // Run the relevant async download task, then call
 // jobFinished once the task is completed.
 jobFinished(params, false);
 }

 // Called when the system stops the job.
 @Override
 public boolean onStopJob(JobParameters params) {
 // Asynchronously record job-related data, such as the
 // stop reason.
 return true; // or return false if job should end entirely
 }
} 
5.   Periodically update the notification to keep the user informed of the job's status and progress. If you cannot determine the transfer size ahead of scheduling the job, or need to update the estimated transfer size, use the new API, `updateEstimatedNetworkBytes()` to update the transfer size after it becomes known.

### Recommendations

To run UIDT jobs effectively, do the following:

1.   Clearly define network constraints and job execution constraints to specify when the job should be executed.

2.   Execute the task asynchronously in `onStartJob()`; for example, you can do this by using a [coroutine](https://developer.android.com/kotlin/coroutines). If you don't run the task asynchronously, the work runs on the main thread and might block it, which can cause an ANR.

3.   To avoid running the job longer than necessary, call [`jobFinished()`](https://developer.android.com/reference/android/app/job/JobService#jobFinished(android.app.job.JobParameters,%20boolean)) when the transfer finishes, whether it succeeds or fails. That way, the job doesn't run longer than necessary. To discover why a job was stopped, implement the [`onStopJob()`](https://developer.android.com/reference/android/app/job/JobService#onStopJob(android.app.job.JobParameters)) callback method and call [`JobParameters.getStopReason()`](https://developer.android.com/reference/android/app/job/JobParameters#getStopReason()).

## Backward compatibility

There is currently no Jetpack library that supports UIDT jobs. For this reason, we recommend that you gate your change with code that verifies that you're running on Android 14 or higher. On lower Android versions, you can use [WorkManager's foreground service implementation](https://developer.android.com/develop/background-work/background-tasks/persistent/how-to/long-running) as a fallback approach.

Here's an example of code that checks for the appropriate system version:

fun beginTask() {
 if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
 scheduleDownloadFGSWorker(context)
 } else {
 scheduleDownloadUIDTJob(context)
 }
}

private fun scheduleDownloadUIDTJob(context: Context) {
 // build jobInfo
 val jobScheduler: JobScheduler =
 context.getSystemService(Context.JOB_SCHEDULER_SERVICE) as JobScheduler
 jobScheduler.schedule(jobInfo)
}

private fun scheduleDownloadFGSWorker(context: Context) {
 val myWorkRequest = OneTimeWorkRequest.from(DownloadWorker::class.java)
 WorkManager.getInstance(context).enqueue(myWorkRequest)
}public void beginTask() {
 if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
 scheduleDownloadFGSWorker(context);
 } else {
 scheduleDownloadUIDTJob(context);
 }
}

private void scheduleDownloadUIDTJob(Context context) {
 // build jobInfo
 JobScheduler jobScheduler =
 (JobScheduler) context.getSystemService(Context.JOB_SCHEDULER_SERVICE);
 jobScheduler.schedule(jobInfo);
}

private void scheduleDownloadFGSWorker(Context context) {
 OneTimeWorkRequest myWorkRequest = OneTimeWorkRequest.from(DownloadWorker.class);
 WorkManager.getInstance(context).enqueue(myWorkRequest)
}

## Stop UIDT jobs

Both the user and the system can stop user-initiated transfer jobs.

### By the user, from Task Manager

The user can stop a user-initiated data transfer job that appears in the [Task Manager](https://developer.android.com/develop/background-work/services/fgs/handle-user-stopping).

At the moment that the user presses **Stop**, the system does the following:

*   Terminates your app's process immediately, including all other jobs or foreground services running.
*   Doesn't call `onStopJob()` for any running jobs.
*   Prevents user-visible jobs from being rescheduled.

For these reasons, it's recommended to provide controls in the notification posted for the job to allow gracefully stopping and rescheduling the job.

Note that, under special circumstances, the **Stop** button doesn't appear next to the job in the Task Manager, or the job isn't shown in the Task Manager at all.

### By the system

Unlike regular jobs, user-initiated data transfer jobs are unaffected by [App Standby Buckets quotas](https://developer.android.com/topic/performance/power/power-details). However, the system still stops the job if any of the following conditions occur:

*   A developer-defined constraint is no longer met.
*   The system determines that the job has run for longer than necessary to complete the data transfer task.
*   The system needs to prioritize system health and stop jobs due to increased thermal state.
*   The app process is killed due to low device memory.

When the job is stopped by the system for reasons _other than_ low device memory, the system calls `onStopJob()`, and the system retries the job at a time that the system deems to be optimal. Make sure that your app can persist the data transfer state even if `onStopJob()` isn't called, and that your app can restore this state when `onStartJob()` is called again.

## Conditions allowed for scheduling user-initiated data transfer jobs

Apps can only start a user-initiated data transfer job if the app is in the visible window, or if certain conditions are met:

*   [If an app can launch activities from the background](https://developer.android.com/guide/components/activities/background-starts#exceptions), it can also launch user-initiated data transfer jobs from the background.
*   If an app has an activity in the back stack of an existing task on the **Recents** screen, that alone doesn't allow a user-initiated data transfer job to run.

If the job is scheduled to run at a time when the necessary conditions are not met, the job fails and returns a `RESULT_FAILURE` error code.

## Constraints that are allowed for user-initiated data transfer jobs

To support jobs running at optimal points, Android offers the ability to assign constraints to each job type. These constraints are available as of Android 13.

**Note**: The following table only compares the constraints that vary between each job type. See [JobScheduler developer page](https://developer.android.com/reference/android/app/job/JobInfo.Builder) or [work constraints](https://developer.android.com/reference/androidx/work/Constraints.Builder) for all constraints.

The following table shows the different job types that support a given job constraint, as well as the set of job constraints that WorkManager supports. Use the search bar before the table to filter the table by the name of a job constraint method.

These are the constraints allowed with user-initiated data transfer jobs:

*   `setBackoffCriteria(JobInfo.BACKOFF_POLICY_EXPONENTIAL)`
*   `setClipData()`
*   `setEstimatedNetworkBytes()`
*   `setMinimumNetworkChunkBytes()`
*   `setPersisted()`
*   `setNamespace()`
*   `setRequiredNetwork()`
*   `setRequiredNetworkType()`
*   `setRequiresBatteryNotLow()`
*   `setRequiresCharging()`
*   `setRequiresStorageNotLow()`

## Testing

The following list shows some steps on how to test your app's jobs manually:

*   To get the job ID, get the value that is defined upon the job being built.
*   To run a job immediately, or to retry a stopped job, run the following command in a terminal window:

adb shell cmd jobscheduler run -f APP_PACKAGE_NAME JOB_ID
*   To simulate the system force-stopping a job (due to system health or out-of-quota conditions), run the following command in a terminal window:

adb shell cmd jobscheduler timeout TEST_APP_PACKAGE TEST_JOB_ID

## See also

*   [Background tasks overview](https://developer.android.com/develop/background-work/background-tasks)
*   [Data transfer background task options](https://developer.android.com/develop/background-work/background-tasks/data-transfer-options)

## Additional resources

For more information about user-initiated data transfers, see the following additional resources:

*   Case study on UIDT integration: [Google Maps improved download reliability by 10% using user initiated data transfer API](https://android-developers.googleblog.com/2024/09/google-maps-improved-download-reliability-user-initiated-data-transfer-api.html)

Title: Support for long-running workers

URL Source: https://developer.android.com/develop/background-work/background-tasks/persistent/how-to/long-running

Markdown Content:
WorkManager has built-in support for long running workers. In such cases, WorkManager can provide a signal to the OS that the process should be kept alive if possible while this work is executing. These Workers can run longer than 10 minutes. Example use-cases for this new feature include bulk uploads or downloads (that cannot be chunked), crunching on an ML model locally, or a task that's _important to the user_ of the app.

Under the hood, WorkManager manages and runs a foreground service on your behalf to execute the [`WorkRequest`](https://developer.android.com/reference/androidx/work/WorkRequest), while also showing a configurable notification.

[`ListenableWorker`](https://developer.android.com/reference/androidx/work/ListenableWorker) now supports the [`setForegroundAsync()`](https://developer.android.com/reference/androidx/work/ListenableWorker#setForegroundAsync(androidx.work.ForegroundInfo)) API, and [`CoroutineWorker`](https://developer.android.com/reference/kotlin/androidx/work/CoroutineWorker) supports a suspending [`setForeground()`](https://developer.android.com/reference/kotlin/androidx/work/CoroutineWorker#setforeground) API. These APIs allow developers to specify that this `WorkRequest` is _important_ (from a user perspective) or _long-running_.

Starting with `2.3.0-alpha03`, WorkManager also allows you to create a [`PendingIntent`](https://developer.android.com/reference/android/app/PendingIntent), which can be used to cancel workers without having to register a new Android component using the [`createCancelPendingIntent()`](https://developer.android.com/reference/androidx/work/WorkManager#createCancelPendingIntent(java.util.UUID)) API. This approach is especially useful when used with the `setForegroundAsync()` or `setForeground()` APIs, which can be used to add a notification action to cancel the `Worker`.

## Creating and managing long-running workers

You'll use a slightly different approach depending on whether you are coding in Kotlin or Java.

### Kotlin

Kotlin developers should use [`CoroutineWorker`](https://developer.android.com/reference/kotlin/androidx/work/CoroutineWorker). Instead of using `setForegroundAsync()`, you can use the suspending version of that method, [`setForeground()`](https://developer.android.com/reference/kotlin/androidx/work/CoroutineWorker#setforeground).

```
class DownloadWorker(context: Context, parameters: WorkerParameters) :
   CoroutineWorker(context, parameters) {

   private val notificationManager =
       context.getSystemService(Context.NOTIFICATION_SERVICE) as
               NotificationManager

   override suspend fun doWork(): Result {
       val inputUrl = inputData.getString(KEY_INPUT_URL)
                      ?: return Result.failure()
       val outputFile = inputData.getString(KEY_OUTPUT_FILE_NAME)
                      ?: return Result.failure()
       // Mark the Worker as important
       val progress = "Starting Download"
       setForeground(createForegroundInfo(progress))
       download(inputUrl, outputFile)
       return Result.success()
   }

   private fun download(inputUrl: String, outputFile: String) {
       // Downloads a file and updates bytes read
       // Calls setForeground() periodically when it needs to update
       // the ongoing Notification
   }
   // Creates an instance of ForegroundInfo which can be used to update the
   // ongoing notification.
   private fun createForegroundInfo(progress: String): ForegroundInfo {
       val id = applicationContext.getString(R.string.notification_channel_id)
       val title = applicationContext.getString(R.string.notification_title)
       val cancel = applicationContext.getString(R.string.cancel_download)
       // This PendingIntent can be used to cancel the worker
       val intent = WorkManager.getInstance(applicationContext)
               .createCancelPendingIntent(getId())

       // Create a Notification channel if necessary
       if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
           createChannel()
       }

       val notification = NotificationCompat.Builder(applicationContext, id)
           .setContentTitle(title)
           .setTicker(title)
           .setContentText(progress)
           .setSmallIcon(R.drawable.ic_work_notification)
           .setOngoing(true)
           // Add the cancel action to the notification which can
           // be used to cancel the worker
           .addAction(android.R.drawable.ic_delete, cancel, intent)
           .build()

       return ForegroundInfo(notificationId, notification)
   }

   @RequiresApi(Build.VERSION_CODES.O)
   private fun createChannel() {
       // Create a Notification channel
   }

   companion object {
       const val KEY_INPUT_URL = "KEY_INPUT_URL"
       const val KEY_OUTPUT_FILE_NAME = "KEY_OUTPUT_FILE_NAME"
   }
}
```

### Java

Developers using a `ListenableWorker` or a `Worker` can call the [`setForegroundAsync()`](https://developer.android.com/reference/androidx/work/ListenableWorker#setForegroundAsync(androidx.work.ForegroundInfo)) API, which returns a `ListenableFuture<Void>`. You can also call `setForegroundAsync()` to update an ongoing `Notification`.

Here is a simple example of a long running worker that downloads a file. This Worker keeps track of progress to update an ongoing `Notification` which shows the download progress.

```
public class DownloadWorker extends Worker {
   private static final String KEY_INPUT_URL = "KEY_INPUT_URL";
   private static final String KEY_OUTPUT_FILE_NAME = "KEY_OUTPUT_FILE_NAME";

   private NotificationManager notificationManager;

   public DownloadWorker(
       @NonNull Context context,
       @NonNull WorkerParameters parameters) {
           super(context, parameters);
           notificationManager = (NotificationManager)
               context.getSystemService(NOTIFICATION_SERVICE);
   }

   @NonNull
   @Override
   public Result doWork() {
       Data inputData = getInputData();
       String inputUrl = inputData.getString(KEY_INPUT_URL);
       String outputFile = inputData.getString(KEY_OUTPUT_FILE_NAME);
       // Mark the Worker as important
       String progress = "Starting Download";
       setForegroundAsync(createForegroundInfo(progress));
       download(inputUrl, outputFile);
       return Result.success();
   }

   private void download(String inputUrl, String outputFile) {
       // Downloads a file and updates bytes read
       // Calls setForegroundAsync(createForegroundInfo(myProgress))
       // periodically when it needs to update the ongoing Notification.
   }

   @NonNull
   private ForegroundInfo createForegroundInfo(@NonNull String progress) {
       // Build a notification using bytesRead and contentLength

       Context context = getApplicationContext();
       String id = context.getString(R.string.notification_channel_id);
       String title = context.getString(R.string.notification_title);
       String cancel = context.getString(R.string.cancel_download);
       // This PendingIntent can be used to cancel the worker
       PendingIntent intent = WorkManager.getInstance(context)
               .createCancelPendingIntent(getId());

       if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
           createChannel();
       }

       Notification notification = new NotificationCompat.Builder(context, id)
               .setContentTitle(title)
               .setTicker(title)
               .setSmallIcon(R.drawable.ic_work_notification)
               .setOngoing(true)
               // Add the cancel action to the notification which can
               // be used to cancel the worker
               .addAction(android.R.drawable.ic_delete, cancel, intent)
               .build();

       return new ForegroundInfo(notificationId, notification);
   }

   @RequiresApi(Build.VERSION_CODES.O)
   private void createChannel() {
       // Create a Notification channel
   }
}
```

## Add a foreground service type to a long-running worker

If your app targets Android 14 (API level 34) or higher you must specify a [foreground service type](https://developer.android.com/develop/background-work/services/fgs/service-types) for all long-running workers. If your app targets Android 10 (API level 29) or higher and contains a long-running worker that requires access to location, indicate that the worker uses a [foreground service type of `location`](https://developer.android.com/develop/background-work/services/fgs/service-types#location).

If your app targets Android 11 (API level 30) or higher and contains a long-running worker that requires access to camera or microphone, declare the [`camera`](https://developer.android.com/develop/background-work/services/fgs/service-types#camera) or [`microphone`](https://developer.android.com/develop/background-work/services/fgs/service-types#microphone) foreground service types, respectively.

To add these foreground service types, complete the steps described in the following sections.

### Declare foreground service types in app manifest

Declare the worker's foreground service type in your app's manifest. In the following example, the worker requires access to location and microphone:

AndroidManifest.xml

<service
 android:name="androidx.work.impl.foreground.SystemForegroundService"
 **android:foregroundServiceType="location|microphone"**
 tools:node="merge" />
### Specify foreground service types at runtime

When you call `setForeground()` or `setForegroundAsync()`, ensure you specify a [foreground service type](https://developer.android.com/develop/background-work/services/fgs/service-types).

MyLocationAndMicrophoneWorker

private fun createForegroundInfo(progress: String): ForegroundInfo {
 // ...
 return ForegroundInfo(NOTIFICATION_ID, notification,
 **FOREGROUND_SERVICE_TYPE_LOCATION or FOREGROUND_SERVICE_TYPE_MICROPHONE**) }@NonNull
private ForegroundInfo createForegroundInfo(@NonNull String progress) {
 // Build a notification...
 Notification notification = ...;
 return new ForegroundInfo(NOTIFICATION_ID, notification,
 **FOREGROUND_SERVICE_TYPE_LOCATION | FOREGROUND_SERVICE_TYPE_MICROPHONE**);
}

Title: Enable multidex for apps with over 64K methods

URL Source: https://developer.android.com/studio/build/multidex

Markdown Content:
If your app has a [`minSdk` of API 20 or lower](https://developer.android.com/studio/build/multidex#mdex-pre-l) and your app and the libraries it references exceed 65,536 methods, you encounter the following build error that indicates your app has reached the limit of the Android build architecture:

trouble writing output:
Too many field references: 131000; max is 65536.
You may try using --multi-dex option.

Older versions of the build system report a different error, which is an indication of the same problem:

Conversion to Dalvik format failed:
Unable to execute dex: method ID not in [0, 0xffff]: 65536

These error conditions display a common number: 65536. This number represents the total number of references that can be invoked by the code within a single Dalvik Executable (DEX) bytecode file. This page explains how to move past this limitation by enabling an app configuration known as _multidex_, which allows your app to build and read multiple DEX files.

## About the 64K reference limit

Android app (APK) files contain executable bytecode files in the form of [Dalvik Executable (DEX)](https://source.android.com/devices/tech/dalvik/dex-format) files, which contain the compiled code used to run your app. The Dalvik Executable specification limits the total number of methods that can be referenced within a single DEX file to 65,536—including Android framework methods, library methods, and methods in your own code.

In the context of computer science, the term [_kilo, or K_](https://en.wikipedia.org/wiki/Kilo-), denotes 1024 (or 2^10). Because 65,536 is equal to 64x1024, this limit is referred to as the _64K reference limit_.

### Multidex support prior to Android 5.0

Versions of the platform prior to Android 5.0 (API level 21) use the Dalvik runtime for executing app code. By default, Dalvik limits apps to a single `classes.dex` bytecode file per APK. To get around this limitation, add the multidex library to the module-level `build.gradle` or `build.gradle.kts` file:

dependencies {
 def multidex_version = "2.0.1"
 implementation "androidx.multidex:multidex:$multidex_version"
}dependencies {
 val multidex_version = "2.0.1"
 implementation("androidx.multidex:multidex:$multidex_version")
}

This library becomes part of the primary DEX file of your app and then manages access to the additional DEX files and the code they contain. To view the current versions for this library, see [multidex versions](https://developer.android.com/jetpack/androidx/releases/multidex#2.0.1).

For more details, see the section about how to [configure your app for multidex](https://developer.android.com/studio/build/multidex#mdex-gradle).

### Multidex support for Android 5.0 and higher

Android 5.0 (API level 21) and higher uses a runtime called ART that natively supports loading multiple DEX files from APK files. ART performs pre-compilation at app install time, scanning for `classesN.dex` files and compiling them into a single OAT file for execution by the Android device. Therefore, if your `minSdkVersion` is 21 or higher, multidex is enabled by default and you don't need the multidex library.

For more information on the Android 5.0 runtime, read [Android Runtime (ART) and Dalvik](https://source.android.com/devices/tech/dalvik/).

**Note:** When running your app using Android Studio, the build is optimized for the target devices you deploy to. This includes enabling multidex when the target devices are running Android 5.0 and higher. Since this optimization is applied only when deploying your app using Android Studio, you might still need to [configure your release build](https://developer.android.com/studio/build/multidex#mdex-gradle) for multidex to avoid the 64K limit.

## Avoid the 64K limit

Before configuring your app to enable use of 64K or more method references, take steps to reduce the total number of references called by your app code, including methods defined by your app code or included libraries.

The following strategies can help you avoid hitting the DEX reference limit:

Review your app's direct and transitive dependencies Consider whether the value of any large library dependency you include in your app outweighs the amount of code being added to the app. A common but problematic pattern is to include a very large library because a few utility methods were useful. Reducing your app code dependencies can often help you avoid the DEX reference limit.Remove unused code with R8[Enable code shrinking](https://developer.android.com/studio/build/shrink-code) to run R8 for your release builds. Enable shrinking to help ensure that you aren't shipping unused code with your APKs. If code shrinking is configured correctly, it can also remove unused code and resources from your dependencies. 
Using these techniques can help you decrease the overall size of your APK and avoid the need for multidex in your app.

## Configure your app for multidex

Note: If your `minSdkVersion` is set to 21 or higher, multidex is enabled by default and you don't need the multidex library.

If your `minSdkVersion` is set to 20 or lower, then you must use the [multidex library](https://developer.android.com/jetpack/androidx/releases/multidex) and make the following modifications to your app project:

1.   Modify the module-level `build.gradle` file to enable multidex and add the multidex library as a dependency, as shown here:

android {
 defaultConfig {
 ...
 minSdkVersion 15 
 targetSdkVersion 36
 **multiDexEnabled true**
 }
 ...
}

dependencies {
 **implementation "androidx.multidex:multidex:2.0.1"**
}android {
 defaultConfig {
 ...
 minSdk = 15 
 targetSdk = 36
 **multiDexEnabled = true**
 }
 ...
}

dependencies {
 **implementation("androidx.multidex:multidex:2.0.1")**
} 
2.   Depending on whether you override the [`Application`](https://developer.android.com/reference/android/app/Application) class, perform one of the following: 
    *   If you don't override the `Application` class, edit your manifest file to set `android:name` in the `<application>` tag as follows:

<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
 package="com.example.myapp">
 <application
 **android:name="androidx.multidex.MultiDexApplication"** >
 ...
 </application>
</manifest>
    *   If you do override the `Application` class, change it to extend `MultiDexApplication`, as follows:

class MyApplication : MultiDexApplication() {...}public class MyApplication extends MultiDexApplication { ... } 
    *   If you override the `Application` class but it's not possible to change the base class, then instead override the [`attachBaseContext()`](https://developer.android.com/reference/android/content/ContextWrapper#attachBaseContext(android.content.Context)) method and call `MultiDex.install(this)` to enable multidex:

class MyApplication : SomeOtherApplication() {

 override fun attachBaseContext(base: Context) {
 super.attachBaseContext(base)
 MultiDex.install(this)
 }
}public class MyApplication extends SomeOtherApplication {
 @Override
 protected void attachBaseContext(Context base) {
 super.attachBaseContext(base);
 MultiDex.install(this);
 }
} 
**Caution:** Don't execute `MultiDex.install()` or any other code through reflection or JNI before `MultiDex.install()` is complete. Multidex tracing will not follow those calls, causing `ClassNotFoundException` or verify errors due to a bad class partition between DEX files.

Now when you build your app, the Android build tools construct a primary DEX file (`classes.dex`) and supporting DEX files (`classes2.dex`, `classes3.dex`, and so on) as needed. The build system then packages all DEX files into your APK.

At runtime, instead of searching only in the main `classes.dex` file, the multidex APIs use a special class loader to search all of the available DEX files for your methods.

### Limitations of the multidex library

The multidex library has some known limitations. When you incorporate the library into your app build configuration, consider the following:

*   The installation of DEX files during startup onto a device's data partition is complex and can result in Application Not Responding (ANR) errors if the secondary DEX files are large. To avoid this issue, [enable code shrinking](https://developer.android.com/studio/build/shrink-code) to minimize the size of DEX files and remove unused portions of code. 
*   When running on versions prior to Android 5.0 (API level 21), using multidex is not enough to work around the linearalloc limit ([issue 37008143](https://issuetracker.google.com/issues/37008143)). This limit was increased in Android 4.0 (API level 14), but that didn't solve the issue completely. 
On versions lower than Android 4.0, you might reach the linearalloc limit before reaching the DEX index limit. So if you are targeting API levels lower than 14, test thoroughly on those versions of the platform, because your app might have issues at startup or when particular groups of classes are loaded.

[Code shrinking](https://developer.android.com/studio/build/shrink-code) can reduce or possibly eliminate these issues.

## Declare classes required in the primary DEX file

When building each DEX file for a multidex app, the build tools perform complex decision-making to determine which classes are needed in the primary DEX file so that your app can start successfully. If any class that's required during startup is not provided in the primary DEX file, then your app crashes with the error `java.lang.NoClassDefFoundError`.

The build tools recognize the code paths for code that's accessed directly from your app code. However, this problem can occur when the code paths are less visible, such as when a library you use has complex dependencies. For example, if the code uses introspection or invocation of Java methods from native code, then those classes might not be recognized as required in the primary DEX file.

If you receive `java.lang.NoClassDefFoundError`, you must manually specify the additional classes required in the primary DEX file by declaring them with the [`multiDexKeepProguard`](https://developer.android.com/reference/tools/gradle-api/9.4/com/android/build/api/dsl/VariantDimension#multiDexKeepProguard()) property in your build type. If a class is matched in the `multiDexKeepProguard` file, then that class is added to the primary DEX file.

### multiDexKeepProguard property

The `multiDexKeepProguard` file uses the same format as ProGuard and supports the entire ProGuard grammar. For more information about how to customize what is kept in your app, see [Customize which code to keep](https://developer.android.com/studio/build/shrink-code#keep-code).

The file you specify in `multiDexKeepProguard` should contain `-keep` options in any valid ProGuard syntax. For example, `-keep com.example.MyClass.class`. You can create a file called `multidex-config.pro` that looks like this:

-keep class com.example.MyClass
-keep class com.example.MyClassToo

If you want to specify all classes in a package, the file looks like this:

-keep class com.example.** { *; } // All classes in the com.example package

Then you can declare that file for a build type, as follows:

android {
 buildTypes {
 release {
 multiDexKeepProguard file('multidex-config.pro')
 ...
 }
 }
}android {
 buildTypes {
 getByName("release") {
 multiDexKeepProguard = file("multidex-config.pro")
 ...
 }
 }
}

## Optimize multidex in development builds

A multidex configuration requires significantly increased build processing time because the build system must make complex decisions about which classes must be included in the primary DEX file and which classes can be included in secondary DEX files. This means that incremental builds using multidex typically take longer and can potentially slow your development process.

To mitigate longer incremental build times, use _pre-dexing_ to reuse multidex output between builds. Pre-dexing relies on an ART format available only on Android 5.0 (API level 21) and higher. If you're using Android Studio, the IDE automatically uses pre-dexing when deploying your app to a device running Android 5.0 (API level 21) or higher. However, if you're running Gradle builds from the command line, you need to set the `minSdkVersion` to 21 or higher to enable pre-dexing.

To preserve settings for your production build, you can create two versions of your app [using product flavors](https://developer.android.com/studio/build/build-variants#product-flavors)—one version with a development flavor and one version with a release flavor—with different values for `minSdkVersion`, as shown:

android {
 defaultConfig {
 ...
 multiDexEnabled true
 // The default minimum API level you want to support.
 minSdkVersion 15
 }
 productFlavors {
 // Includes settings you want to keep only while developing your app.
 dev {
 // Enables pre-dexing for command-line builds. When using
 // Android Studio 2.3 or higher, the IDE enables pre-dexing
 // when deploying your app to a device running Android 5.0
 // (API level 21) or higher, regardless of minSdkVersion.
 minSdkVersion 21
 }
 prod {
 // If you've configured the defaultConfig block for the production version of
 // your app, you can leave this block empty and Gradle uses configurations in
 // the defaultConfig block instead. You still need to include this flavor.
 // Otherwise, all variants use the "dev" flavor configurations.
 }
 }
 buildTypes {
 release {
 minifyEnabled true
 proguardFiles getDefaultProguardFile('proguard-android.txt'),
 'proguard-rules.pro'
 }
 }
}
dependencies {
 implementation "androidx.multidex:multidex:2.0.1"
}android {
 defaultConfig {
 ...
 multiDexEnabled = true
 // The default minimum API level you want to support.
 minSdk = 15
 }
 productFlavors {
 // Includes settings you want to keep only while developing your app.
 create("dev") {
 // Enables pre-dexing for command-line builds. When using
 // Android Studio 2.3 or higher, the IDE enables pre-dexing
 // when deploying your app to a device running Android 5.0
 // (API level 21) or higher, regardless of minSdkVersion.
 minSdk = 21
 }
 create("prod") {
 // If you've configured the defaultConfig block for the production version of
 // your app, you can leave this block empty and Gradle uses configurations in
 // the defaultConfig block instead. You still need to include this flavor.
 // Otherwise, all variants use the "dev" flavor configurations.
 }
 }
 buildTypes {
 getByName("release") {
 isMinifyEnabled = true
 proguardFiles(getDefaultProguardFile("proguard-android.txt"),
 "proguard-rules.pro")
 }
 }
}

dependencies {
 implementation("androidx.multidex:multidex:2.0.1")
}

To learn more strategies to help improve build speeds from either Android Studio or the command line, read [Optimize your build speed](https://developer.android.com/studio/build/optimize-your-build). For more information about using build variants, see [Configure build variants](https://developer.android.com/studio/build/build-variants).

**Tip:** If you have different build variants for different multidex needs, you can provide a different manifest file for each variant so only the file for API level 20 and lower changes the `<application>` tag name. You can also create a different `Application` subclass for each variant so only the subclass for API level 20 and lower extends the `MultiDexApplication` class or calls `MultiDex.install(this)`.

When you write instrumentation tests for multidex apps, no additional configuration is required if you use a [`MonitoringInstrumentation`](https://developer.android.com/reference/androidx/test/runner/MonitoringInstrumentation) or an [`AndroidJUnitRunner`](https://developer.android.com/reference/androidx/test/runner/AndroidJUnitRunner) instrumentation. If you use another [`Instrumentation`](https://developer.android.com/reference/android/app/Instrumentation), then you must override its `onCreate()` method with the following code:

fun onCreate(arguments: Bundle) {
 MultiDex.install(targetContext)
 super.onCreate(arguments)
 ...
}public void onCreate(Bundle arguments) {
 MultiDex.install(getTargetContext());
 super.onCreate(arguments);
 ...
}

### Registering background fetch with minimum interval for testing on Android

Source: https://docs.expo.dev/versions/latest/sdk/background-fetch

