import type { Context } from "grammy";
import type { AppContainer } from "../../app/bootstrap/app-container.js";
import type { PermissionReply } from "../../app/types/permission.js";
import { opencodeClient, opencodeServerVersion } from "../../opencode/client.js";
import { getCurrentProject } from "../../app/stores/settings-store.js";
import { getCurrentSession } from "../../app/services/session-service.js";
import {
  applyPermissionPromptChanges,
  clearPermissionInteraction,
  showPermissionDeliveryWarning,
} from "../menus/permission-menu.js";
import { t } from "../../i18n/index.js";
import { logger } from "../../utils/logger.js";
import { safeBackgroundTask } from "../../utils/safe-background-task.js";

function getCallbackMessageId(ctx: Context): number | null {
  const message = ctx.callbackQuery?.message;
  if (!message || !("message_id" in message)) {
    return null;
  }

  const messageId = (message as { message_id?: number }).message_id;
  return typeof messageId === "number" ? messageId : null;
}

function isPermissionReply(value: string): value is PermissionReply {
  return value === "once" || value === "always" || value === "reject";
}

function isPermissionRequestNotFound(error: unknown): boolean {
  if (!error || typeof error !== "object") {
    return false;
  }

  const candidate = error as {
    _tag?: unknown;
    name?: unknown;
    message?: unknown;
    data?: { message?: unknown };
  };

  if (candidate._tag === "PermissionNotFoundError") {
    return true;
  }

  if (candidate.name === "NotFoundError") {
    return true;
  }

  return [candidate.message, candidate.data?.message].some(
    (message) =>
      typeof message === "string" && message.toLowerCase().includes("permission request not found"),
  );
}

export type PermissionCallbackDeps = Pick<
  AppContainer,
  "interactionManager" | "permissionManager" | "summaryAggregator"
>;

export async function handlePermissionCallback(
  ctx: Context,
  deps: PermissionCallbackDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data) return false;

  if (!data.startsWith("permission:")) {
    return false;
  }

  logger.debug(`[PermissionHandler] Received callback: ${data}`);

  if (!deps.permissionManager.isActive()) {
    clearPermissionInteraction("permission_inactive_callback", deps);
    await ctx.answerCallbackQuery({ text: t("permission.inactive_callback"), show_alert: true });
    return true;
  }

  const callbackMessageId = getCallbackMessageId(ctx);
  if (!deps.permissionManager.isActiveMessage(callbackMessageId)) {
    await ctx.answerCallbackQuery({ text: t("permission.inactive_callback"), show_alert: true });
    return true;
  }

  const requestIDs = deps.permissionManager.getRequestIDs(callbackMessageId);
  if (requestIDs.length === 0) {
    await ctx.answerCallbackQuery({ text: t("permission.inactive_callback"), show_alert: true });
    return true;
  }

  const parts = data.split(":");
  const action = parts[1];

  if (!action || !isPermissionReply(action)) {
    await ctx.answerCallbackQuery({
      text: t("permission.processing_error_callback"),
      show_alert: true,
    });
    return true;
  }

  try {
    await handlePermissionReply(ctx, deps, action, requestIDs, callbackMessageId);
  } catch (err) {
    logger.error("[PermissionHandler] Error handling callback:", err);
    await ctx.answerCallbackQuery({
      text: t("permission.processing_error_callback"),
      show_alert: true,
    });
  }

  return true;
}

async function handlePermissionReply(
  ctx: Context,
  deps: PermissionCallbackDeps,
  reply: PermissionReply,
  requestIDs: string[],
  callbackMessageId: number | null,
): Promise<void> {
  const currentProject = getCurrentProject();
  const currentSession = getCurrentSession();
  const chatId = ctx.chat?.id;
  const directory = currentSession?.directory ?? currentProject?.worktree;

  if (!directory || !chatId) {
    deps.permissionManager.clear();
    clearPermissionInteraction("permission_invalid_runtime_context", deps);

    await ctx.answerCallbackQuery({
      text: t("permission.no_active_request_callback"),
      show_alert: true,
    });
    return;
  }

  const replyLabels: Record<PermissionReply, string> = {
    once: t("permission.reply.once"),
    always: t("permission.reply.always"),
    reject: t("permission.reply.reject"),
  };

  // On V2 a reject settles every pending request of the session.
  const settlesSession = reply === "reject" && opencodeServerVersion === "v2";
  if (
    callbackMessageId === null ||
    !deps.permissionManager.markSending(callbackMessageId, reply, settlesSession)
  ) {
    // The first answer is still on its way: a second tap changes nothing.
    await ctx.answerCallbackQuery();
    return;
  }

  // The answer is marked as being sent: a lost toast must not keep it from going out.
  await ctx.answerCallbackQuery({ text: replyLabels[reply] }).catch((err) => {
    logger.warn("[PermissionHandler] Failed to answer the permission callback:", err);
  });

  deps.summaryAggregator.stopTypingIndicator();

  logger.info(
    `[PermissionHandler] Sending permission reply: ${reply}, requestIDs=${requestIDs.join(",")}`,
  );

  const messageId = callbackMessageId;
  const sessionID = deps.permissionManager.getRequest(messageId)?.sessionID ?? null;

  safeBackgroundTask({
    taskName: "permission.reply",
    task: async () => {
      const results: PermissionReplyResults = { accepted: [], gone: [], failed: [] };

      for (const requestID of requestIDs) {
        const response = await opencodeClient.permission.reply({
          requestID,
          directory,
          reply,
        });

        if (!response.error) {
          results.accepted.push(requestID);
        } else if (isPermissionRequestNotFound(response.error)) {
          logger.debug(
            `[PermissionHandler] Permission request already resolved: requestID=${requestID}`,
          );
          results.gone.push(requestID);
        } else {
          logger.error(
            `[PermissionHandler] Failed to send permission reply: requestID=${requestID}`,
            response.error,
          );
          results.failed.push(requestID);
        }
      }

      return results;
    },
    onSuccess: (results) => {
      void finishPermissionReply(ctx.api, chatId, deps, {
        messageId,
        sessionID,
        reply,
        settlesSession,
        results,
      });
    },
    onError: () => {
      void finishPermissionReply(ctx.api, chatId, deps, {
        messageId,
        sessionID,
        reply,
        settlesSession,
        results: { accepted: [], gone: [], failed: requestIDs },
      });
    },
  });
}

interface PermissionReplyResults {
  accepted: string[];
  gone: string[];
  failed: string[];
}

interface FinishedPermissionReply {
  messageId: number;
  sessionID: string | null;
  reply: PermissionReply;
  settlesSession: boolean;
  results: PermissionReplyResults;
}

/**
 * Ends the prompt once OpenCode took the answer, or leaves it answerable with a warning
 * when the answer did not get through. A prompt an event or a reset already ended stays
 * as it is.
 */
async function finishPermissionReply(
  api: Context["api"],
  chatId: number,
  deps: PermissionCallbackDeps,
  finished: FinishedPermissionReply,
): Promise<void> {
  const { messageId, sessionID, reply, settlesSession, results } = finished;

  try {
    if (results.failed.length > 0) {
      const change = deps.permissionManager.failSending(messageId, results.accepted);
      if (change && change.outcome) {
        await applyPermissionPromptChanges(api, chatId, [change], deps);
      } else if (change) {
        await showPermissionDeliveryWarning(api, chatId, change, deps);
      }
      return;
    }

    const answered = results.accepted.length > 0;
    const change = deps.permissionManager.endPrompt(
      messageId,
      answered ? { kind: "replied", reply, outside: false } : { kind: "settled_outside" },
    );
    const changes = change ? [change] : [];

    if (answered && settlesSession && sessionID) {
      changes.push(
        ...deps.permissionManager.endSessionPrompts(sessionID, {
          kind: "replied",
          reply: "reject",
          outside: false,
        }),
      );
    }

    await applyPermissionPromptChanges(api, chatId, changes, deps);
    logger.info(`[PermissionHandler] Permission reply finished: messageId=${messageId}`);
  } catch (err) {
    logger.error("[PermissionHandler] Failed to finish permission reply:", err);
  }
}

import type { Context } from "grammy";
import type { AppContainer } from "../../app/bootstrap/app-container.js";
import { opencodeClient } from "../../opencode/client.js";
import { getCurrentProject } from "../../app/stores/settings-store.js";
import { getCurrentSession } from "../../app/services/session-service.js";
import {
  clearQuestionInteraction,
  closeQuestionCancelled,
  closeQuestionSettledOutside,
  isQuestionRequestGone,
  showCurrentQuestion,
  showNextQuestion,
  showQuestionDeliveryWarning,
  submitPollAnswers,
  syncQuestionInteractionState,
  updateQuestionMessage,
  type QuestionReplyResult,
} from "../menus/question-menu.js";
import { t } from "../../i18n/index.js";
import { logger } from "../../utils/logger.js";
import { safeBackgroundTask } from "../../utils/safe-background-task.js";
import { alert } from "./feedback.js";

export type QuestionCallbackDeps = Pick<
  AppContainer,
  "interactionManager" | "questionManager" | "summaryAggregator"
>;

function getCallbackMessageId(ctx: Context): number | null {
  const message = ctx.callbackQuery?.message;
  if (!message || !("message_id" in message)) {
    return null;
  }

  const messageId = (message as { message_id?: number }).message_id;
  return typeof messageId === "number" ? messageId : null;
}

/** The poll's last question: answering it sends the whole poll to OpenCode. */
function isLastQuestion(deps: QuestionCallbackDeps, questionIndex: number): boolean {
  return questionIndex === deps.questionManager.getTotalQuestions() - 1;
}

export async function handleQuestionCallback(
  ctx: Context,
  deps: QuestionCallbackDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data) return false;

  if (!data.startsWith("question:")) {
    return false;
  }

  logger.debug(`[QuestionHandler] Received callback: ${data}`);

  if (!deps.questionManager.isActive()) {
    clearQuestionInteraction("question_inactive_callback", deps);
    await ctx.answerCallbackQuery({ text: t("question.inactive_callback"), show_alert: true });
    return true;
  }

  const callbackMessageId = getCallbackMessageId(ctx);
  if (!deps.questionManager.isActiveMessage(callbackMessageId)) {
    await ctx.answerCallbackQuery({ text: t("question.inactive_callback"), show_alert: true });
    return true;
  }

  if (deps.questionManager.isSettlingFromTelegram()) {
    // The answers or the dismissal are on their way: no button does anything until they land.
    await ctx.answerCallbackQuery();
    return true;
  }

  deps.questionManager.clearLastCancelFailed();

  const parts = data.split(":");
  const action = parts[1];
  const questionIndex = parseInt(parts[2] ?? "", 10);

  if (Number.isNaN(questionIndex) || questionIndex !== deps.questionManager.getCurrentIndex()) {
    await ctx.answerCallbackQuery({ text: t("question.inactive_callback"), show_alert: true });
    return true;
  }

  try {
    switch (action) {
      case "select":
        {
          const optionIndex = parseInt(parts[3] ?? "", 10);
          if (Number.isNaN(optionIndex)) {
            await ctx.answerCallbackQuery({
              text: t("question.processing_error_callback"),
              show_alert: true,
            });
            break;
          }

          await handleSelectOption(ctx, deps, questionIndex, optionIndex);
        }
        break;
      case "submit":
        await handleSubmitAnswer(ctx, deps, questionIndex);
        break;
      case "custom":
        await handleCustomAnswer(ctx, deps, questionIndex);
        break;
      case "toggle_custom":
        await handleToggleCustomAnswer(ctx, deps, questionIndex);
        break;
      case "cancel":
        await handleCancelPoll(ctx, deps);
        break;
      default:
        await ctx.answerCallbackQuery({
          text: t("question.processing_error_callback"),
          show_alert: true,
        });
        break;
    }
  } catch (err) {
    logger.error("[QuestionHandler] Error handling callback:", err);
    await ctx.answerCallbackQuery({
      text: t("question.processing_error_callback"),
      show_alert: true,
    });
  }

  return true;
}

async function handleSelectOption(
  ctx: Context,
  deps: QuestionCallbackDeps,
  questionIndex: number,
  optionIndex: number,
): Promise<void> {
  logger.debug(
    `[QuestionHandler] handleSelectOption: qIndex=${questionIndex}, oIndex=${optionIndex}`,
  );

  const question = deps.questionManager.getCurrentQuestion();
  if (!question) {
    logger.debug("[QuestionHandler] No current question");
    await alert(ctx, "question.inactive_callback");
    return;
  }

  if (deps.questionManager.isWaitingForCustomInput(questionIndex)) {
    deps.questionManager.clearCustomInput();
    syncQuestionInteractionState(
      "callback",
      questionIndex,
      deps.questionManager.getActiveMessageId(),
      deps,
    );
  }

  deps.questionManager.selectOption(questionIndex, optionIndex);

  if (question.multiple) {
    logger.debug("[QuestionHandler] Multiple choice mode, updating message");
    await updateQuestionMessage(ctx, deps);
    await ctx.answerCallbackQuery();
  } else {
    logger.debug("[QuestionHandler] Single choice mode, moving to next question");
    const requestID = deps.questionManager.getRequestID();
    await ctx.answerCallbackQuery();

    const answer = deps.questionManager.getSelectedAnswer(questionIndex);
    logger.debug(`[QuestionHandler] Selected answer for question ${questionIndex}: ${answer}`);

    await answerStep(ctx, deps, questionIndex, requestID);
  }
}

async function handleSubmitAnswer(
  ctx: Context,
  deps: QuestionCallbackDeps,
  questionIndex: number,
): Promise<void> {
  if (deps.questionManager.isWaitingForCustomInput(questionIndex)) {
    deps.questionManager.clearCustomInput();
    syncQuestionInteractionState(
      "callback",
      questionIndex,
      deps.questionManager.getActiveMessageId(),
      deps,
    );
  }

  if (!deps.questionManager.hasAnswer(questionIndex)) {
    await ctx.answerCallbackQuery({
      text: t("question.select_one_required_callback"),
      show_alert: true,
    });
    return;
  }

  logger.debug(
    `[QuestionHandler] Submit answer for question ${questionIndex}: ${deps.questionManager.getAnswerItems(questionIndex).join(" | ")}`,
  );

  const requestID = deps.questionManager.getRequestID();
  await ctx.answerCallbackQuery();
  await answerStep(ctx, deps, questionIndex, requestID);
}

/**
 * A question was answered: the last one sends the poll's answers and stays on screen until
 * OpenCode takes them, an earlier one gives way to the next question. A poll that was closed
 * while the tap was being acknowledged (settled outside Telegram, a reset) is left as it is.
 */
async function answerStep(
  ctx: Context,
  deps: QuestionCallbackDeps,
  questionIndex: number,
  requestID: string | null,
): Promise<void> {
  if (deps.questionManager.getRequestID() !== requestID || !deps.questionManager.isActive()) {
    logger.info(`[QuestionHandler] Poll closed while its tap was handled: requestID=${requestID}`);
    return;
  }

  if (isLastQuestion(deps, questionIndex)) {
    if (ctx.chat) {
      await submitPollAnswers(ctx.api, ctx.chat.id, deps);
    }
    return;
  }

  await ctx.deleteMessage().catch(() => {});
  await showNextQuestion(ctx, deps);
}

async function handleCustomAnswer(
  ctx: Context,
  deps: QuestionCallbackDeps,
  questionIndex: number,
): Promise<void> {
  deps.questionManager.startCustomInput(questionIndex);
  syncQuestionInteractionState(
    "mixed",
    questionIndex,
    deps.questionManager.getActiveMessageId(),
    deps,
  );

  await ctx.answerCallbackQuery({
    text: t("question.enter_custom_callback"),
    show_alert: true,
  });
}

async function handleToggleCustomAnswer(
  ctx: Context,
  deps: QuestionCallbackDeps,
  questionIndex: number,
): Promise<void> {
  if (deps.questionManager.isWaitingForCustomInput(questionIndex)) {
    deps.questionManager.clearCustomInput();
    syncQuestionInteractionState(
      "callback",
      questionIndex,
      deps.questionManager.getActiveMessageId(),
      deps,
    );
  }

  deps.questionManager.toggleCustomAnswer(questionIndex);

  await updateQuestionMessage(ctx, deps);
  await ctx.answerCallbackQuery();
}

async function handleCancelPoll(ctx: Context, deps: QuestionCallbackDeps): Promise<void> {
  const { questionManager } = deps;
  const requestID = questionManager.getRequestID();
  const directory = getCurrentSession()?.directory ?? getCurrentProject()?.worktree;
  const chatId = ctx.chat?.id;

  if (!requestID || !directory || chatId === undefined) {
    // Nothing can be sent: the poll stays answerable and says the Cancel did not get through.
    logger.error("[QuestionHandler] No requestID or project for dismissing the question");
    await ctx.answerCallbackQuery();
    if (chatId !== undefined) {
      await showQuestionDeliveryWarning(ctx.api, chatId, deps);
    }
    return;
  }

  questionManager.startDismissal();
  syncQuestionInteractionState(
    "callback",
    questionManager.getCurrentIndex(),
    questionManager.getActiveMessageId(),
    deps,
  );

  // The dismissal is marked as being sent: a lost toast must not keep it from going out.
  await ctx.answerCallbackQuery({ text: t("common.cancelled") }).catch((err) => {
    logger.warn("[QuestionHandler] Failed to answer the cancel callback:", err);
  });

  logger.info(`[QuestionHandler] Dismissing question via question.reject: requestID=${requestID}`);

  safeBackgroundTask({
    taskName: "question.reject",
    task: async (): Promise<QuestionReplyResult> => {
      const { error } = await opencodeClient.question.reject({ requestID, directory });
      if (!error) {
        return "accepted";
      }

      if (isQuestionRequestGone(error)) {
        logger.debug(`[QuestionHandler] Question already settled: requestID=${requestID}`);
        return "gone";
      }

      logger.error(`[QuestionHandler] Failed to dismiss question: requestID=${requestID}`, error);
      return "failed";
    },
    onSuccess: (result) => finishDismissal(ctx.api, chatId, deps, requestID, result),
    onError: () => finishDismissal(ctx.api, chatId, deps, requestID, "failed"),
  });
}

/**
 * Ends the poll once OpenCode answered the dismissal, or leaves it answerable with a
 * warning when the dismissal did not get through. A poll something else already ended
 * stays as it is.
 */
async function finishDismissal(
  api: Context["api"],
  chatId: number,
  deps: QuestionCallbackDeps,
  requestID: string,
  result: QuestionReplyResult,
): Promise<void> {
  const { questionManager } = deps;
  if (!questionManager.isDismissing() || questionManager.getRequestID() !== requestID) {
    logger.info(`[QuestionHandler] Dismissal finished for a poll already closed: ${requestID}`);
    return;
  }

  const settled = questionManager.getSettledWhileSending();
  logger.info(
    `[QuestionHandler] Dismissal finished: requestID=${requestID}, result=${result}, settled=${settled ?? "none"}`,
  );

  if (settled === "answered") {
    await closeQuestionSettledOutside(api, chatId, "answered", deps);
  } else if (result === "gone") {
    await closeQuestionSettledOutside(api, chatId, "cancelled", deps);
  } else if (result === "accepted" || settled === "cancelled") {
    // A lost reply still counts when OpenCode reported the question dismissed.
    await closeQuestionCancelled(api, chatId, deps);
  } else {
    questionManager.failDismissal();
    await showQuestionDeliveryWarning(api, chatId, deps);
  }
}

export async function handleQuestionTextAnswer(
  ctx: Context,
  deps: QuestionCallbackDeps,
): Promise<void> {
  const text = ctx.message?.text;
  if (!text) return;

  const currentIndex = deps.questionManager.getCurrentIndex();

  if (!deps.questionManager.isWaitingForCustomInput(currentIndex)) {
    await ctx.reply(t("question.use_custom_button_first"));
    return;
  }

  const multiple = deps.questionManager.getCurrentQuestion()?.multiple ?? false;

  if (!multiple && deps.questionManager.hasCustomAnswer(currentIndex)) {
    await ctx.reply(t("question.answer_already_received"));
    return;
  }

  logger.debug(`[QuestionHandler] Custom text answer for question ${currentIndex}: ${text}`);

  deps.questionManager.setCustomAnswer(currentIndex, text);
  deps.questionManager.clearCustomInput();

  if (!multiple && isLastQuestion(deps, currentIndex)) {
    if (ctx.chat) {
      await submitPollAnswers(ctx.api, ctx.chat.id, deps);
    }
    return;
  }

  const activeMessageId = deps.questionManager.getActiveMessageId();
  if (activeMessageId !== null && ctx.chat) {
    await ctx.api.deleteMessage(ctx.chat.id, activeMessageId).catch(() => {});
  }

  if (multiple) {
    // A multi-select question stays open: re-send it below the user's text with the custom row.
    if (ctx.chat) {
      await showCurrentQuestion(ctx.api, ctx.chat.id, deps);
    }
    return;
  }

  await showNextQuestion(ctx, deps);
}

import type { Context } from "grammy";
import {
  MAX_QUEUED_PROMPTS,
  MAX_QUEUED_MEDIA_BYTES,
  promptQueue,
  type QueuedPromptInput,
} from "../../app/managers/prompt-queue-manager.js";
import { promptHandover, type ArrivalTicket } from "../../app/managers/prompt-handover-manager.js";
import type { IncomingPrompt } from "../../app/types/prompt.js";
import { buildExternalUserInputNotification } from "../../app/services/external-user-input-service.js";
import {
  cancelInboxPrompt,
  reconcileInboxPrompts,
} from "../../app/services/prompt-inbox-service.js";
import { isForegroundBusy } from "../../app/services/run-control-service.js";
import { getCurrentSession } from "../../app/services/session-service.js";
import { getPromptQueueMode } from "../../app/stores/settings-store.js";
import { t } from "../../i18n/index.js";
import { opencodeServerVersion } from "../../opencode/client.js";
import { logger } from "../../utils/logger.js";
import { sendBotText } from "../messages/telegram-text.js";
import { isReplyKeyboardButtonText } from "../message-patterns.js";
import {
  admitPromptToInbox,
  processUserPrompt,
  startInboxPromptRun,
  type ProcessPromptDeps,
} from "./prompt.js";
import { handOverPreparedPrompt } from "./prompt-handover.js";

// The queue helpers are called from the guard and the media handlers without
// deps, so the dispatcher receives them once at startup instead. Until then the
// chat counts as not busy and nothing is queued.
let promptDeps: ProcessPromptDeps | null = null;

// Live context of the last queued message, replayed when the queue drains.
// Same approach as message-merger.ts.
let queuedPromptContext: Context | null = null;

// Both drain sites fire unawaited, and processUserPrompt only marks the session
// busy after several network round-trips. Without this flag two overlapping
// drains could each pass the busy check and start a second run for the same
// session, losing the prompt the loser took off the queue.
let dispatchInFlight = false;

export function initializePromptQueueDispatch(deps: ProcessPromptDeps): void {
  promptDeps = deps;
}

function isBusy(): boolean {
  return promptDeps !== null && (isForegroundBusy(promptDeps) || waitsForHandedOverPrompts());
}

/** Prompts handed over to the current session at /detach go before anything sent since. */
function waitsForHandedOverPrompts(): boolean {
  const session = getCurrentSession();
  return Boolean(session && promptHandover.hasPendingPrompts(session.id));
}

function isPromptQueueEnabled(): boolean {
  return getPromptQueueMode() !== "off";
}

/** On OpenCode V2 busy-time prompts wait in the session inbox, not in the bot. */
function usesOpencodeInbox(): boolean {
  return opencodeServerVersion === "v2";
}

/** Whether the text is user prompt content rather than a command or a button press. */
function isQueueablePrompt(input: IncomingPrompt): boolean {
  const normalizedText = input.text.trim();
  const hasContent =
    Boolean(normalizedText) || input.fileParts.length > 0 || input.photos.length > 0;
  return (
    hasContent &&
    !normalizedText.startsWith("/") &&
    !isReplyKeyboardButtonText(input.text)
  );
}

/**
 * Whether the user should be told that this message could have been queued.
 * True only when the setting is off and the text would otherwise have been queued.
 */
export function shouldSuggestPromptQueue(input: IncomingPrompt): boolean {
  return !isPromptQueueEnabled() && isQueueablePrompt(input);
}

export function canQueueMediaPrompt(ctx: Context): boolean {
  const message = ctx.message;
  return Boolean(
    isPromptQueueEnabled() &&
      message &&
      (message.voice || message.audio || message.photo?.length || message.document),
  );
}

/**
 * Queues a prepared prompt that arrived while the session was busy.
 * Returns false when queueing does not apply, so the caller keeps its old behaviour.
 */
export async function tryEnqueuePrompt(ctx: Context, input: QueuedPromptInput): Promise<boolean> {
  if (!promptDeps || !isPromptQueueEnabled() || !ctx.chat || !isQueueablePrompt(input)) {
    return false;
  }

  if (usesOpencodeInbox()) {
    await sendPromptToInbox(ctx, input, promptDeps);
    return true;
  }

  queuedPromptContext = ctx;

  if (promptQueue.isFull()) {
    logger.info(`[PromptQueue] Rejected prompt: queue is full (max=${MAX_QUEUED_PROMPTS})`);
    await replyWithKeyboard(ctx, t("queue.full", { max: String(MAX_QUEUED_PROMPTS) }));
    return true;
  }

  if (!promptQueue.canAcceptMedia(input.mediaBytes ?? 0)) {
    await replyWithKeyboard(ctx, t("queue.media_limit", { maxSizeMb: formatQueuedMediaLimit() }));
    return true;
  }

  const queued = promptQueue.add(input);
  if (!queued) {
    return false;
  }

  logger.info(
    `[PromptQueue] Prompt queued while session is busy: size=${promptQueue.size()}/${MAX_QUEUED_PROMPTS}`,
  );
  await replyWithKeyboard(
    ctx,
    t("queue.added", { count: String(promptQueue.size()), max: String(MAX_QUEUED_PROMPTS) }),
  );
  return true;
}

/**
 * Sends a busy-time prompt into the OpenCode V2 session inbox and mirrors it as a queue
 * item. The reservation keeps the cap honest while the prompt is on its way and tells
 * whether the queue was cleared in the meantime.
 */
async function sendPromptToInbox(
  ctx: Context,
  input: QueuedPromptInput,
  deps: ProcessPromptDeps,
): Promise<void> {
  const delivery = getPromptQueueMode() === "steer" ? "steer" : "queue";
  const reservationId = promptQueue.reserve();
  if (!reservationId) {
    logger.info(`[PromptQueue] Rejected inbox prompt: queue is full (max=${MAX_QUEUED_PROMPTS})`);
    await replyWithKeyboard(ctx, t("queue.full", { max: String(MAX_QUEUED_PROMPTS) }));
    return;
  }

  const admitted = await admitPromptToInbox(ctx, input, deps, delivery);
  if (!admitted) {
    promptQueue.releaseReservation(reservationId);
    promptQueue.releaseHandedOverReservation(reservationId);
    return;
  }

  const inbox = { sessionId: admitted.sessionId, inboxId: admitted.inboxId, delivery } as const;

  // Handed over by /detach while on its way: it stays with that session, and nothing is shown.
  if (promptQueue.releaseHandedOverReservation(reservationId)) {
    promptHandover.addInboxEntry(inbox);
    return;
  }

  // OpenCode may deliver the prompt before the send returns (the turn had just ended):
  // the pickup has already been shown, so there is no button, only the run to open.
  if (promptQueue.wasInboxIdDelivered(admitted.inboxId)) {
    if (!promptQueue.releaseReservation(reservationId)) {
      return;
    }
    if (!deps.assistantRunState.hasBotRun(admitted.sessionId)) {
      const session = getCurrentSession();
      if (session?.id === admitted.sessionId) {
        await startInboxPromptRun(session, deps, input.responseMode);
      }
    }
    await replyInboxAdmission(ctx, delivery);
    return;
  }

  const item = promptQueue.confirmReservation(reservationId, {
    displayText: input.displayText ?? input.text,
    inbox,
    ...(input.responseMode ? { responseMode: input.responseMode } : {}),
  });
  if (!item) {
    // Cleared by /abort or a session change while the prompt was on its way.
    await cancelInboxPrompt(inbox, "withdrawn_during_admission");
    return;
  }

  logger.info(
    `[PromptQueue] Prompt sent to the session inbox: delivery=${delivery}, size=${promptQueue.size()}/${MAX_QUEUED_PROMPTS}`,
  );
  await replyInboxAdmission(ctx, delivery);
}

async function replyInboxAdmission(ctx: Context, delivery: "steer" | "queue"): Promise<void> {
  const params = { count: String(promptQueue.size()), max: String(MAX_QUEUED_PROMPTS) };
  await replyWithKeyboard(
    ctx,
    delivery === "steer" ? t("queue.steer_added", params) : t("queue.added", params),
  );
}

/**
 * The session a message arriving now would wait for, taken before the message is
 * prepared; undefined when it would not wait.
 */
export function takeArrivalTicket(): ArrivalTicket | undefined {
  const session = getCurrentSession();
  if (!session || !isPromptQueueEnabled() || !isBusy()) {
    return undefined;
  }
  return promptHandover.takeTicket(session.id);
}

/**
 * Queues a prepared prompt when the session is busy. A message whose preparation
 * outlived /detach goes to the session it arrived for, as one sent right before.
 */
export async function tryEnqueuePromptIfBusy(
  ctx: Context,
  input: QueuedPromptInput,
  ticket?: ArrivalTicket,
): Promise<boolean> {
  if (ticket && promptHandover.wasDetachedSince(ticket) && isQueueablePrompt(input)) {
    return handOverPreparedPrompt(ctx, ticket, input);
  }
  return isBusy() && tryEnqueuePrompt(ctx, input);
}

/**
 * Rejects a busy queued-media candidate before handlers download or encode it.
 * Media sizes are raw Telegram file_size values, not expanded data-URI bytes.
 */
export async function rejectQueuedMediaBeforePreparation(
  ctx: Context,
  mediaBytes: number | undefined,
): Promise<boolean> {
  if (!isBusy() || !isPromptQueueEnabled() || !ctx.chat) {
    return false;
  }
  if (promptQueue.isFull()) {
    await replyWithKeyboard(ctx, t("queue.full", { max: String(MAX_QUEUED_PROMPTS) }));
    return true;
  }
  // Nothing is held by the bot on V2, so the queued media cap does not apply there.
  if (usesOpencodeInbox()) {
    return false;
  }
  if (
    typeof mediaBytes !== "number" ||
    !Number.isSafeInteger(mediaBytes) ||
    mediaBytes < 0 ||
    !promptQueue.canAcceptMedia(mediaBytes)
  ) {
    await replyWithKeyboard(ctx, t("queue.media_limit", { maxSizeMb: formatQueuedMediaLimit() }));
    return true;
  }
  return false;
}

function formatQueuedMediaLimit(): string {
  return String(MAX_QUEUED_MEDIA_BYTES / (1024 * 1024));
}

/**
 * Sends the next queued prompt once the session is idle again, echoing it in the
 * same "external user input" format used for prompts sent from another device.
 */
export async function dispatchNextQueuedPrompt(): Promise<void> {
  // On V2 OpenCode delivers waiting prompts itself; the idle point only drops mirror
  // items whose pickup or cancel the bot missed.
  if (usesOpencodeInbox()) {
    const session = getCurrentSession();
    if (session) {
      await reconcileInboxPrompts(session.id);
    }
    return;
  }

  if (
    dispatchInFlight ||
    promptQueue.size() === 0 ||
    !promptDeps ||
    !queuedPromptContext ||
    isBusy()
  ) {
    return;
  }

  dispatchInFlight = true;

  try {
    const item = promptQueue.takeNext();
    if (!item) {
      return;
    }

    const ctx = queuedPromptContext;
    const deps = promptDeps;

    const notification = buildExternalUserInputNotification(item.displayText);
    if (notification && ctx.chat) {
      try {
        const keyboard = deps.keyboardManager.getKeyboard();
        await sendBotText({
          api: ctx.api,
          chatId: ctx.chat.id,
          text: notification.text,
          rawFallbackText: notification.rawFallbackText,
          format: "markdown_v2",
          options: keyboard ? { reply_markup: keyboard } : {},
        });
      } catch (err) {
        logger.error("[PromptQueue] Failed to echo queued prompt:", err);
      }
    }

    logger.info(
      `[PromptQueue] Dispatching queued prompt: id=${item.id}, left=${promptQueue.size()}`,
    );

    try {
      const dispatched = await processUserPrompt(ctx, item, deps, {
        ...(item.responseMode ? { responseMode: item.responseMode } : {}),
      });
      if (!dispatched) {
        logger.warn(`[PromptQueue] Queued prompt was not dispatched: id=${item.id}`);
      }
    } catch (err) {
      logger.error(`[PromptQueue] Failed to dispatch queued prompt: id=${item.id}`, err);
    }
  } finally {
    dispatchInFlight = false;
  }
}

async function replyWithKeyboard(ctx: Context, text: string): Promise<void> {
  const keyboard = promptDeps?.keyboardManager.getKeyboard();
  await ctx.reply(text, keyboard ? { reply_markup: keyboard } : {}).catch((err) => {
    logger.error("[PromptQueue] Failed to send queue reply:", err);
  });
}

/** Test helper: clears the stored context and dependencies. */
export function __resetPromptQueueDispatchForTests(): void {
  promptDeps = null;
  queuedPromptContext = null;
  dispatchInFlight = false;
}

import type { Bot, Context } from "grammy";
import type { AppContainer } from "../../app/bootstrap/app-container.js";
import { config } from "../../config.js";
import type { InteractionState } from "../../app/types/interaction.js";
import { opencodeClient } from "../../opencode/client.js";
import { setCurrentSession } from "../../app/services/session-service.js";
import { applySessionSettings } from "../../app/services/session-settings-service.js";
import { getStoredAgent } from "../../app/services/agent-selection-service.js";
import { getStoredModel } from "../../app/services/model-selection-service.js";
import type { SessionInfo } from "../../app/types/session.js";
import { attachToSession } from "../../app/services/attach-service.js";
import { ingestSessionInfoForCache } from "../../app/services/session-cache-service.js";
import { loadLatestAssistantResponse } from "../../app/services/message-history-service.js";
import type { UserMessageItem } from "../../app/services/message-history-service.js";
import { isForegroundBusy } from "../../app/services/run-control-service.js";
import { t } from "../../i18n/index.js";
import { logger } from "../../utils/logger.js";
import { cancelMenu } from "./feedback.js";
import { safeBackgroundTask } from "../../utils/safe-background-task.js";
import { renderAssistantFinalPartsSafe } from "../messages/assistant-rendering.js";
import { replyBusyBlocked } from "../messages/busy-blocked-renderer.js";
import { sendRenderedBotPart } from "../messages/telegram-text.js";
import {
  buildMessageDetailKeyboard,
  buildMessagesListKeyboard,
  calculateMessagesPaginationRange,
  formatMessageDetailText,
  formatMessagesSelectText,
  MESSAGES_CALLBACK_BACK,
  MESSAGES_CALLBACK_CANCEL,
  MESSAGES_CALLBACK_FORK,
  MESSAGES_CALLBACK_PREFIX,
  MESSAGES_CALLBACK_REVERT,
  parseMessagePageCallback,
  parseMessageSelectCallback,
  TELEGRAM_MESSAGE_LIMIT,
  truncateMessageHistoryText,
} from "../menus/message-history-menu.js";

export type MessagesCallbackDeps = Pick<
  AppContainer,
  | "attachManager"
  | "ensureEventSubscription"
  | "foregroundSessionState"
  | "interactionManager"
  | "keyboardManager"
  | "permissionManager"
  | "questionManager"
  | "resetInteractions"
  | "summaryAggregator"
> & {
  bot: Bot<Context>;
};

interface MessagesListMetadata {
  flow: "messages";
  stage: "list";
  messageId: number;
  projectDirectory: string;
  sessionId: string;
  messages: UserMessageItem[];
  page: number;
}

interface MessagesDetailMetadata {
  flow: "messages";
  stage: "detail";
  messageId: number;
  projectDirectory: string;
  sessionId: string;
  messages: UserMessageItem[];
  page: number;
  selectedIndex: number;
}

type MessagesMetadata = MessagesListMetadata | MessagesDetailMetadata;

function getCallbackMessageId(ctx: Context): number | null {
  const message = ctx.callbackQuery?.message;
  if (!message || !("message_id" in message)) {
    return null;
  }

  const messageId = (message as { message_id?: number }).message_id;
  return typeof messageId === "number" ? messageId : null;
}

function parseMessages(value: unknown): UserMessageItem[] | null {
  if (!Array.isArray(value)) {
    return null;
  }

  const messages: UserMessageItem[] = [];
  for (const item of value) {
    if (!item || typeof item !== "object") {
      return null;
    }

    const id = (item as { id?: unknown }).id;
    const text = (item as { text?: unknown }).text;
    const created = (item as { created?: unknown }).created;

    if (typeof id !== "string" || typeof text !== "string" || typeof created !== "number") {
      return null;
    }

    messages.push({ id, text, created });
  }

  return messages;
}

function parseMessagesMetadata(state: InteractionState | null): MessagesMetadata | null {
  if (!state || state.kind !== "custom") {
    return null;
  }

  const flow = state.metadata.flow;
  const stage = state.metadata.stage;
  const messageId = state.metadata.messageId;
  const projectDirectory = state.metadata.projectDirectory;
  const sessionId = state.metadata.sessionId;
  const messages = parseMessages(state.metadata.messages);
  const page =
    typeof state.metadata.page === "number" && Number.isInteger(state.metadata.page)
      ? Math.max(0, state.metadata.page)
      : 0;

  if (
    flow !== "messages" ||
    typeof messageId !== "number" ||
    typeof projectDirectory !== "string" ||
    typeof sessionId !== "string" ||
    !messages
  ) {
    return null;
  }

  if (stage === "list") {
    return {
      flow,
      stage,
      messageId,
      projectDirectory,
      sessionId,
      messages,
      page,
    };
  }

  if (stage === "detail") {
    const selectedIndex = state.metadata.selectedIndex;
    if (typeof selectedIndex !== "number" || !Number.isInteger(selectedIndex) || selectedIndex < 0) {
      return null;
    }

    return {
      flow,
      stage,
      messageId,
      projectDirectory,
      sessionId,
      messages,
      page,
      selectedIndex,
    };
  }

  return null;
}

function clearMessagesInteraction(deps: MessagesCallbackDeps, reason: string): void {
  const metadata = parseMessagesMetadata(deps.interactionManager.getSnapshot());
  if (metadata) {
    deps.interactionManager.clear(reason);
  }
}

async function sendLatestAssistantResponse(
  api: Context["api"],
  chatId: number,
  sessionId: string,
  directory: string,
): Promise<void> {
  const responseText = await loadLatestAssistantResponse(sessionId, directory);
  if (!responseText) {
    return;
  }

  const parts = renderAssistantFinalPartsSafe(responseText);
  for (const part of parts) {
    await sendRenderedBotPart({
      api,
      chatId,
      part,
    });
  }
}

export async function handleMessagesCallback(
  ctx: Context,
  deps: MessagesCallbackDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data || !data.startsWith(MESSAGES_CALLBACK_PREFIX)) {
    return false;
  }

  if (isForegroundBusy(deps)) {
    await replyBusyBlocked(ctx);
    return true;
  }

  const metadata = parseMessagesMetadata(deps.interactionManager.getSnapshot());
  const callbackMessageId = getCallbackMessageId(ctx);

  if (!metadata || callbackMessageId === null || metadata.messageId !== callbackMessageId) {
    await ctx.answerCallbackQuery({ text: t("messages.inactive_callback"), show_alert: true });
    return true;
  }

  try {
    if (data === MESSAGES_CALLBACK_REVERT) {
      if (metadata.stage !== "detail") {
        await ctx.answerCallbackQuery({ text: t("messages.inactive_callback"), show_alert: true });
        return true;
      }

      const selectedMessage = metadata.messages[metadata.selectedIndex];
      if (!selectedMessage) {
        await ctx.answerCallbackQuery({ text: t("messages.fetch_error"), show_alert: true });
        return true;
      }

      await ctx.answerCallbackQuery();

      try {
        await opencodeClient.session.revert({
          sessionID: metadata.sessionId,
          directory: metadata.projectDirectory,
          messageID: selectedMessage.id,
        });

        const successText = t("messages.revert_success", { text: selectedMessage.text });
        await ctx.editMessageText(truncateMessageHistoryText(successText, TELEGRAM_MESSAGE_LIMIT));
        clearMessagesInteraction(deps, "messages_revert_success");
      } catch (error) {
        logger.error("[Messages] Error reverting message:", error);
        await ctx.editMessageText(t("messages.revert_error"));
        clearMessagesInteraction(deps, "messages_revert_error");
      }

      return true;
    }

    if (data === MESSAGES_CALLBACK_FORK) {
      if (metadata.stage !== "detail") {
        await ctx.answerCallbackQuery({ text: t("messages.inactive_callback"), show_alert: true });
        return true;
      }

      const selectedMessage = metadata.messages[metadata.selectedIndex];
      if (!selectedMessage) {
        await ctx.answerCallbackQuery({ text: t("messages.fetch_error"), show_alert: true });
        return true;
      }

      await ctx.answerCallbackQuery();

      try {
        const { data: forkedSession, error: forkError } = await opencodeClient.session.fork({
          sessionID: metadata.sessionId,
          messageID: selectedMessage.id,
          directory: metadata.projectDirectory,
        });

        if (forkError || !forkedSession) {
          throw forkError || new Error("No session data received from fork");
        }

        logger.info(
          `[Messages] Forked session: id=${forkedSession.id}, title="${forkedSession.title}", from message=${selectedMessage.id}`,
        );

        const sessionInfo: SessionInfo = {
          id: forkedSession.id,
          title: forkedSession.title,
          directory: metadata.projectDirectory,
        };

        setCurrentSession(sessionInfo);
        // Pull before attaching, so the pinned message rendered inside
        // attachToSession already carries the forked session's model.
        await applySessionSettings(forkedSession);
        deps.keyboardManager.updateAgent(getStoredAgent());
        deps.keyboardManager.updateModel(getStoredModel());
        deps.resetInteractions("session_forked");
        await ingestSessionInfoForCache(forkedSession);

        await attachToSession({
          ...deps,
          chatId: ctx.chat!.id,
          session: sessionInfo,
        });

        const successText = t("messages.fork_success", { text: selectedMessage.text });
        await ctx.editMessageText(truncateMessageHistoryText(successText, TELEGRAM_MESSAGE_LIMIT));
        clearMessagesInteraction(deps, "messages_fork_success");

        safeBackgroundTask({
          taskName: "messages.sendLatestAssistantResponse",
          task: () =>
            sendLatestAssistantResponse(
              ctx.api,
              ctx.chat!.id,
              forkedSession.id,
              metadata.projectDirectory,
            ),
        });
      } catch (error) {
        logger.error("[Messages] Error forking session:", error);
        await ctx.editMessageText(t("messages.fork_error"));
        clearMessagesInteraction(deps, "messages_fork_error");
      }

      return true;
    }

    if (data === MESSAGES_CALLBACK_BACK) {
      if (metadata.stage !== "detail") {
        await ctx.answerCallbackQuery({ text: t("messages.inactive_callback"), show_alert: true });
        return true;
      }

      const pageSize = config.bot.messagesListLimit;
      const { page: normalizedPage } = calculateMessagesPaginationRange(
        metadata.messages.length,
        metadata.page,
        pageSize,
      );
      await ctx.answerCallbackQuery();
      await ctx.editMessageText(formatMessagesSelectText(normalizedPage), {
        reply_markup: buildMessagesListKeyboard(metadata.messages, normalizedPage, pageSize),
      });

      deps.interactionManager.transition({
        expectedInput: "callback",
        metadata: {
          flow: "messages",
          stage: "list",
          messageId: metadata.messageId,
          projectDirectory: metadata.projectDirectory,
          sessionId: metadata.sessionId,
          messages: metadata.messages,
          page: normalizedPage,
        },
      });

      return true;
    }

    if (data === MESSAGES_CALLBACK_CANCEL) {
      clearMessagesInteraction(deps, "messages_cancelled");
      await cancelMenu(ctx);
      return true;
    }

    const page = parseMessagePageCallback(data);
    if (page !== null) {
      if (metadata.stage !== "list") {
        await ctx.answerCallbackQuery({ text: t("callback.processing_error") });
        return true;
      }

      const pageSize = config.bot.messagesListLimit;
      const { page: normalizedPage, totalPages } = calculateMessagesPaginationRange(
        metadata.messages.length,
        page,
        pageSize,
      );

      if (page >= totalPages || page < 0) {
        await ctx.answerCallbackQuery({ text: t("messages.page_empty_callback") });
        return true;
      }

      await ctx.answerCallbackQuery();
      await ctx.editMessageText(formatMessagesSelectText(normalizedPage), {
        reply_markup: buildMessagesListKeyboard(metadata.messages, normalizedPage, pageSize),
      });

      deps.interactionManager.transition({
        expectedInput: "callback",
        metadata: {
          flow: "messages",
          stage: "list",
          messageId: metadata.messageId,
          projectDirectory: metadata.projectDirectory,
          sessionId: metadata.sessionId,
          messages: metadata.messages,
          page: normalizedPage,
        },
      });

      return true;
    }

    const messageIndex = parseMessageSelectCallback(data);
    if (messageIndex === null || metadata.stage !== "list") {
      await ctx.answerCallbackQuery({ text: t("callback.processing_error") });
      return true;
    }

    const selectedMessage = metadata.messages[messageIndex];
    if (!selectedMessage) {
      await ctx.answerCallbackQuery({ text: t("messages.inactive_callback"), show_alert: true });
      return true;
    }

    await ctx.answerCallbackQuery();
    await ctx.editMessageText(formatMessageDetailText(selectedMessage), {
      reply_markup: buildMessageDetailKeyboard(),
    });

    deps.interactionManager.transition({
      expectedInput: "callback",
      metadata: {
        flow: "messages",
        stage: "detail",
        messageId: metadata.messageId,
        projectDirectory: metadata.projectDirectory,
        sessionId: metadata.sessionId,
        messages: metadata.messages,
        page: metadata.page,
        selectedIndex: messageIndex,
      },
    });

    return true;
  } catch (error) {
    logger.error("[Messages] Error handling messages callback:", error);
    clearMessagesInteraction(deps, "messages_callback_error");
    await ctx.answerCallbackQuery({ text: t("callback.processing_error") }).catch(() => {});
    return true;
  }
}

import { Context, InlineKeyboard } from "grammy";
import type { AppContainer } from "../../app/bootstrap/app-container.js";
import { getStoredAgent, resolveProjectAgent } from "../../app/services/agent-selection-service.js";
import {
  fetchCurrentModel,
  getModelAvailability,
  getModelSelectionLists,
  getProviderModels,
  getProviders,
  searchModels,
  selectModel,
} from "../../app/services/model-selection-service.js";
import { formatVariantForButton } from "../../app/services/variant-selection-service.js";
import { formatModelForDisplay } from "../../app/types/model.js";
import type { FavoriteModel, ModelInfo, ProviderInfo } from "../../app/types/model.js";
import { logger } from "../../utils/logger.js";
import { t } from "../../i18n/index.js";
import { cancelMenu, failure, switched } from "./feedback.js";
import { createMainKeyboard } from "../keyboards/main-reply-keyboard.js";
import {
  appendInlineMenuCancelButton,
  clearActiveInlineMenu,
  ensureActiveInlineMenu,
} from "../menus/inline-menu.js";
import { showVariantSelectionMenuAfterModelChange } from "../menus/variant-selection-menu.js";
import {
  buildModelRootMenuView,
  buildProviderModelsMenuView,
  buildProvidersMenuView,
  MODEL_LIST_CALLBACK_PREFIX,
  MODEL_PROVIDER_CALLBACK_PREFIX,
  MODEL_PROVIDER_MODEL_CALLBACK_PREFIX,
  MODEL_PROVIDERS_CALLBACK_PREFIX,
  MODEL_ROOT_CALLBACK,
  MODEL_SEARCH_AGAIN_CALLBACK,
  MODEL_SEARCH_CALLBACK,
  MODEL_SEARCH_CANCEL_CALLBACK,
  parseProviderCallback,
  parseProviderModelCallback,
  parseProvidersPageCallback,
} from "../menus/model-selection-menu.js";

const MODEL_SEARCH_RESULT_CALLBACK_PREFIX = "model:result:";

interface ModelSearchMetadata {
  flow: string;
  stage: string;
  messageId?: number | undefined;
  query: string;
  models: ModelInfo[];
}

interface ModelListMetadata {
  favorites: ModelInfo[];
  recent: ModelInfo[];
}

export type ModelSelectionDeps = Pick<
  AppContainer,
  "interactionManager" | "keyboardManager" | "pinnedMessageManager"
>;

function parseModelItems(value: unknown): ModelInfo[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.flatMap((item) => {
    if (
      typeof item !== "object" ||
      item === null ||
      !("providerID" in item) ||
      !("modelID" in item)
    ) {
      return [];
    }

    const providerID = item.providerID;
    const modelID = item.modelID;
    if (typeof providerID !== "string" || typeof modelID !== "string") {
      return [];
    }

    const variant =
      "variant" in item && typeof item.variant === "string" ? item.variant : "default";
    return [{ providerID, modelID, variant }];
  });
}

function parseModelSearchMetadata(deps: ModelSelectionDeps): ModelSearchMetadata | null {
  const state = deps.interactionManager.getSnapshot();
  if (!state || state.kind !== "custom") {
    return null;
  }

  const flow = state.metadata.flow;
  const stage = state.metadata.stage;

  if (flow !== "model-search" || typeof stage !== "string") {
    return null;
  }

  const messageId =
    typeof state.metadata.messageId === "number" ? state.metadata.messageId : undefined;
  const query = typeof state.metadata.query === "string" ? state.metadata.query : "";

  return { flow, stage, messageId, query, models: parseModelItems(state.metadata.models) };
}

function parseModelListMetadata(deps: ModelSelectionDeps): ModelListMetadata | null {
  const state = deps.interactionManager.getSnapshot();
  if (!state || state.kind !== "inline" || state.metadata.menuKind !== "model") {
    return null;
  }

  const modelLists = state.metadata.modelLists;
  if (typeof modelLists !== "object" || modelLists === null) {
    return null;
  }

  return {
    favorites: parseModelItems("favorites" in modelLists ? modelLists.favorites : undefined),
    recent: parseModelItems("recent" in modelLists ? modelLists.recent : undefined),
  };
}

function parseNonNegativeIndex(value: string): number | null {
  if (!/^\d+$/.test(value)) {
    return null;
  }

  const index = Number.parseInt(value, 10);
  if (!Number.isInteger(index) || index < 0) {
    return null;
  }

  return index;
}

function parseCallbackIndex(data: string, prefix: string): number | null {
  if (!data.startsWith(prefix)) {
    return null;
  }

  return parseNonNegativeIndex(data.slice(prefix.length));
}

function resolveModelListCallback(deps: ModelSelectionDeps, data: string): ModelInfo | null {
  if (!data.startsWith(MODEL_LIST_CALLBACK_PREFIX)) {
    return null;
  }

  const parts = data.slice(MODEL_LIST_CALLBACK_PREFIX.length).split(":");
  if (parts.length !== 2) {
    return null;
  }

  const [kind, indexText] = parts;
  if (!kind || !indexText) {
    return null;
  }
  const index = parseNonNegativeIndex(indexText);
  if ((kind !== "favorites" && kind !== "recent") || index === null) {
    return null;
  }

  const lists = parseModelListMetadata(deps);
  if (!lists) {
    return null;
  }

  const model = kind === "favorites" ? lists.favorites[index] : lists.recent[index];
  if (!model) {
    return null;
  }

  return {
    providerID: model.providerID,
    modelID: model.modelID,
    variant: "default",
  };
}

function parseLegacyModelCallback(data: string): ModelInfo | null {
  const parts = data.split(":");
  if (parts.length < 3) {
    return null;
  }

  const providerID = parts[1];
  const modelID = parts.slice(2).join(":");
  if (!providerID || !modelID) {
    return null;
  }

  return {
    providerID,
    modelID,
    variant: "default",
  };
}

function isShortModelCallback(data: string): boolean {
  return (
    data.startsWith(MODEL_SEARCH_RESULT_CALLBACK_PREFIX) ||
    data.startsWith(MODEL_LIST_CALLBACK_PREFIX) ||
    isProviderBrowserCallback(data)
  );
}

function isProviderBrowserCallback(data: string): boolean {
  return (
    data === MODEL_ROOT_CALLBACK ||
    data.startsWith(MODEL_PROVIDERS_CALLBACK_PREFIX) ||
    data.startsWith(MODEL_PROVIDER_CALLBACK_PREFIX) ||
    data.startsWith(MODEL_PROVIDER_MODEL_CALLBACK_PREFIX)
  );
}

function parseProviderItems(value: unknown): ProviderInfo[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.flatMap((item) => {
    if (typeof item !== "object" || item === null || !("id" in item) || !("name" in item)) {
      return [];
    }

    const { id, name } = item as { id: unknown; name: unknown };
    if (typeof id !== "string" || typeof name !== "string") {
      return [];
    }

    const modelCount =
      "modelCount" in item && typeof (item as { modelCount: unknown }).modelCount === "number"
        ? (item as { modelCount: number }).modelCount
        : 0;

    return [{ id, name, modelCount }];
  });
}

interface ProviderBrowserMetadata {
  providers: ProviderInfo[];
  providersPage: number;
  providerIndex: number | null;
  providerModelsPage: number;
  models: ModelInfo[];
}

function parseProviderBrowserMetadata(deps: ModelSelectionDeps): ProviderBrowserMetadata | null {
  const state = deps.interactionManager.getSnapshot();
  if (!state || state.kind !== "inline" || state.metadata.menuKind !== "model") {
    return null;
  }

  return {
    providers: parseProviderItems(state.metadata.providers),
    providersPage:
      typeof state.metadata.providersPage === "number" ? state.metadata.providersPage : 0,
    providerIndex:
      typeof state.metadata.providerIndex === "number" ? state.metadata.providerIndex : null,
    providerModelsPage:
      typeof state.metadata.providerModelsPage === "number" ? state.metadata.providerModelsPage : 0,
    models: parseModelItems(state.metadata.models),
  };
}

function updateModelMenuMetadata(
  deps: ModelSelectionDeps,
  metadata: Record<string, unknown>,
): void {
  const state = deps.interactionManager.getSnapshot();

  deps.interactionManager.transition({
    expectedInput: "callback",
    metadata: {
      ...metadata,
      menuKind: "model",
      messageId: state?.metadata.messageId,
    },
  });
}

async function renderModelMenuScreen(
  ctx: Context,
  view: { text: string; keyboard: InlineKeyboard },
): Promise<void> {
  await ctx.answerCallbackQuery().catch(() => {});
  await ctx.editMessageText(view.text, {
    reply_markup: appendInlineMenuCancelButton(view.keyboard, "model"),
  });
}

async function showProvidersScreen(
  ctx: Context,
  deps: ModelSelectionDeps,
  page: number,
): Promise<void> {
  const providers = await getProviders();
  const view = buildProvidersMenuView(providers, page);

  await renderModelMenuScreen(ctx, view);
  updateModelMenuMetadata(deps, { providers, providersPage: view.page });
}

async function showModelRootScreen(ctx: Context, deps: ModelSelectionDeps): Promise<void> {
  const modelLists = await getModelSelectionLists();
  const view = await buildModelRootMenuView(fetchCurrentModel(), modelLists);

  await renderModelMenuScreen(ctx, view);
  updateModelMenuMetadata(deps, { modelLists });
}

async function showProviderModelsScreen(
  ctx: Context,
  deps: ModelSelectionDeps,
  meta: ProviderBrowserMetadata,
  provider: ProviderInfo,
  providerIndex: number,
  page: number,
): Promise<void> {
  const models = await getProviderModels(provider.id);
  const view = buildProviderModelsMenuView(
    provider,
    providerIndex,
    models,
    page,
    meta.providersPage,
    fetchCurrentModel(),
  );

  await renderModelMenuScreen(ctx, view);
  updateModelMenuMetadata(deps, {
    providers: meta.providers,
    providersPage: meta.providersPage,
    providerIndex,
    providerModelsPage: view.page,
    models: view.pageModels.map((model) => ({
      providerID: model.providerID,
      modelID: model.modelID,
      variant: "default",
    })),
  });
}

function buildModelSearchResultsView(
  query: string,
  results: FavoriteModel[],
): { text: string; keyboard: InlineKeyboard } {
  const keyboard = new InlineKeyboard();

  for (const [index, model] of results.entries()) {
    const label = `${model.providerID}/${model.modelID}`;
    keyboard.text(label, `${MODEL_SEARCH_RESULT_CALLBACK_PREFIX}${index}`).row();
  }

  keyboard.row();
  keyboard.text(t("model.search.search_again"), MODEL_SEARCH_AGAIN_CALLBACK);
  keyboard.text(t("inline.button.cancel"), MODEL_SEARCH_CANCEL_CALLBACK);

  const text =
    results.length === 0
      ? t("model.search.no_results", { query })
      : t("model.search.results_title", { query });

  return { text, keyboard };
}

function transitionToModelSearchResults(
  deps: ModelSelectionDeps,
  query: string,
  messageId: number | undefined,
  results: FavoriteModel[],
): void {
  deps.interactionManager.transition({
    expectedInput: "callback",
    metadata: {
      flow: "model-search",
      stage: "results",
      messageId,
      query,
      models: results.map((model) => ({
        providerID: model.providerID,
        modelID: model.modelID,
        variant: "default",
      })),
    },
  });
}

async function showModelSearchResultsAgain(
  ctx: Context,
  deps: ModelSelectionDeps,
  meta: ModelSearchMetadata,
): Promise<void> {
  const results = await searchModels(meta.query);
  const view = buildModelSearchResultsView(meta.query, results);

  await ctx.answerCallbackQuery().catch(() => {});
  await ctx.editMessageText(view.text, { reply_markup: view.keyboard });
  transitionToModelSearchResults(deps, meta.query, meta.messageId, results);
}

// A model can leave OpenCode after the menu showing it was drawn. When the list cannot be
// read the tap goes through as before.
async function isModelStillOffered(modelInfo: ModelInfo): Promise<boolean> {
  const availability = await getModelAvailability(modelInfo.providerID, modelInfo.modelID);
  return availability === "offered" || availability === "unknown";
}

/**
 * Redraw the screen a tap on a model OpenCode no longer offers came from, without a
 * message: the model is gone from the current list.
 */
async function redrawAfterStaleModelTap(ctx: Context, redraw: () => Promise<void>): Promise<void> {
  try {
    await redraw();
  } catch (err) {
    logger.debug("[ModelHandler] Could not redraw the model menu after a stale tap:", err);
    await ctx.answerCallbackQuery().catch(() => {});
  }
}

/**
 * Shared logic for applying a model selection and updating UI.
 * Used by both the regular inline menu flow and the search results flow.
 */
async function applyModelSelectionAndNotify(
  ctx: Context,
  deps: ModelSelectionDeps,
  modelInfo: ModelInfo,
): Promise<void> {
  if (ctx.chat) {
    deps.keyboardManager.initialize(ctx.api, ctx.chat.id);
  }

  selectModel(modelInfo);
  deps.keyboardManager.updateModel(modelInfo);
  await deps.pinnedMessageManager.refreshContextLimit();

  const currentAgent = await resolveProjectAgent(getStoredAgent());
  const contextInfo =
    deps.pinnedMessageManager.getContextInfo() ??
    (deps.pinnedMessageManager.getContextLimit() > 0
      ? { tokensUsed: 0, tokensLimit: deps.pinnedMessageManager.getContextLimit() }
      : null);

  deps.keyboardManager.updateAgent(currentAgent);

  if (contextInfo) {
    deps.keyboardManager.updateContext(contextInfo.tokensUsed, contextInfo.tokensLimit);
  }

  const variantName = formatVariantForButton(modelInfo.variant || "default");
  const keyboard = createMainKeyboard(
    currentAgent,
    modelInfo,
    contextInfo ?? undefined,
    variantName,
  );
  const displayName = formatModelForDisplay(modelInfo.providerID, modelInfo.modelID);

  await switched(ctx, t("model.changed_message", { name: displayName }), keyboard);
  await showVariantSelectionMenuAfterModelChange(ctx, modelInfo, deps);
}

/**
 * Handle model selection callback from the inline menu.
 * Skips search-related callbacks (handled separately).
 * @returns true if handled, false otherwise
 */
export async function handleModelSelect(ctx: Context, deps: ModelSelectionDeps): Promise<boolean> {
  const callbackQuery = ctx.callbackQuery;

  if (!callbackQuery?.data || !callbackQuery.data.startsWith("model:")) {
    return false;
  }

  // Skip search callbacks — handled by handleModelSearchCallback / handleModelSearchResults
  if (
    callbackQuery.data === MODEL_SEARCH_CALLBACK ||
    callbackQuery.data === MODEL_SEARCH_AGAIN_CALLBACK ||
    callbackQuery.data === MODEL_SEARCH_CANCEL_CALLBACK
  ) {
    return false;
  }

  // Skip provider browser callbacks — handled by handleModelProvidersCallback
  if (isProviderBrowserCallback(callbackQuery.data)) {
    return false;
  }

  const isActiveMenu = await ensureActiveInlineMenu(ctx, "model", deps);
  if (!isActiveMenu) {
    return true;
  }

  logger.debug(`[ModelHandler] Received callback: ${callbackQuery.data}`);

  try {
    const modelInfo = resolveModelListCallback(deps, callbackQuery.data);
    const shouldUseLegacyFallback = !isShortModelCallback(callbackQuery.data);
    const resolvedModelInfo =
      modelInfo ?? (shouldUseLegacyFallback ? parseLegacyModelCallback(callbackQuery.data) : null);

    if (!resolvedModelInfo) {
      logger.error(`[ModelHandler] Invalid callback data format: ${callbackQuery.data}`);
      clearActiveInlineMenu("model_select_invalid_callback", deps);
      await ctx.answerCallbackQuery({ text: t("model.change_error_callback") }).catch(() => {});
      return true;
    }

    if (!(await isModelStillOffered(resolvedModelInfo))) {
      await redrawAfterStaleModelTap(ctx, () => showModelRootScreen(ctx, deps));
      return true;
    }

    clearActiveInlineMenu("model_selected", deps);
    await applyModelSelectionAndNotify(ctx, deps, resolvedModelInfo);

    return true;
  } catch (err) {
    clearActiveInlineMenu("model_select_error", deps);
    logger.error("[ModelHandler] Error handling model select:", err);
    await failure(ctx, "model.change_error_callback");
    return true;
  }
}

/**
 * Handle the provider browser callbacks from the model inline menu:
 * - model:root — back to the favorites/recent menu
 * - model:providers:<page> — providers list
 * - model:provider:<providerIndex>:<page> — models of a provider
 * - model:pick:<index> — select a model from the current provider page
 * @returns true if handled, false otherwise
 */
export async function handleModelProvidersCallback(
  ctx: Context,
  deps: ModelSelectionDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data || !isProviderBrowserCallback(data)) {
    return false;
  }

  const isActiveMenu = await ensureActiveInlineMenu(ctx, "model", deps);
  if (!isActiveMenu) {
    return true;
  }

  logger.debug(`[ModelHandler] Received provider browser callback: ${data}`);

  try {
    if (data === MODEL_ROOT_CALLBACK) {
      await showModelRootScreen(ctx, deps);
      return true;
    }

    const providersPage = parseProvidersPageCallback(data);
    if (providersPage !== null) {
      await showProvidersScreen(ctx, deps, providersPage);
      return true;
    }

    const providerCallback = parseProviderCallback(data);
    if (providerCallback) {
      const meta = parseProviderBrowserMetadata(deps);
      const provider = meta?.providers[providerCallback.providerIndex];

      if (!provider) {
        logger.warn(`[ModelHandler] Unresolved provider callback: ${data}`);
        await ctx
          .answerCallbackQuery({ text: t("inline.inactive_callback"), show_alert: true })
          .catch(() => {});
        return true;
      }

      await showProviderModelsScreen(
        ctx,
        deps,
        meta,
        provider,
        providerCallback.providerIndex,
        providerCallback.page,
      );
      return true;
    }

    const modelIndex = parseProviderModelCallback(data);
    if (modelIndex !== null) {
      const meta = parseProviderBrowserMetadata(deps);
      const modelInfo = meta?.models[modelIndex];

      if (!modelInfo) {
        logger.warn(`[ModelHandler] Unresolved provider model callback: ${data}`);
        await ctx.answerCallbackQuery({ text: t("model.change_error_callback") }).catch(() => {});
        return true;
      }

      if (!(await isModelStillOffered(modelInfo))) {
        const { providerIndex } = meta;
        const provider = providerIndex === null ? undefined : meta.providers[providerIndex];
        await redrawAfterStaleModelTap(ctx, () =>
          provider && providerIndex !== null
            ? showProviderModelsScreen(
                ctx,
                deps,
                meta,
                provider,
                providerIndex,
                meta.providerModelsPage,
              )
            : showModelRootScreen(ctx, deps),
        );
        return true;
      }

      clearActiveInlineMenu("model_selected", deps);
      await applyModelSelectionAndNotify(ctx, deps, modelInfo);
      return true;
    }

    return false;
  } catch (err) {
    logger.error("[ModelHandler] Error handling provider browser callback:", err);
    await ctx.answerCallbackQuery({ text: t("model.providers.error") }).catch(() => {});
    return true;
  }
}

/**
 * Handle the search button callback (model:search) from the inline menu.
 * Transitions the interaction to text-input mode and prompts the user.
 */
export async function handleModelSearchCallback(
  ctx: Context,
  deps: ModelSelectionDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data) {
    return false;
  }

  if (data !== MODEL_SEARCH_CALLBACK) {
    return false;
  }

  const isActive = await ensureActiveInlineMenu(ctx, "model", deps);
  if (!isActive) {
    return true;
  }

  await ctx.answerCallbackQuery().catch(() => {});
  await ctx.deleteMessage().catch(() => {});

  // Start a new interaction for search text input
  // deps.interactionManager.start() clears any existing interaction automatically
  deps.interactionManager.start({
    kind: "custom",
    expectedInput: "text",
    metadata: {
      flow: "model-search",
      stage: "input",
    },
  });

  await ctx.reply(t("model.search.prompt"));

  logger.debug("[ModelHandler] Model search prompt shown");
  return true;
}

/**
 * Handle text input for model search.
 * Searches the full provider catalog and shows results (or "not found").
 */
export async function handleModelSearchTextInput(
  ctx: Context,
  deps: ModelSelectionDeps,
): Promise<boolean> {
  const meta = parseModelSearchMetadata(deps);
  if (!meta || meta.stage !== "input") {
    return false;
  }

  const text = ctx.message?.text;
  if (text === undefined) {
    return false;
  }

  if (!text.trim()) {
    return true;
  }

  logger.debug(`[ModelHandler] Model search query: "${text}"`);

  try {
    const results = await searchModels(text);
    const view = buildModelSearchResultsView(text, results);

    const sent = await ctx.reply(view.text, { reply_markup: view.keyboard });

    // Transition to results stage (callback-only)
    transitionToModelSearchResults(deps, text, sent.message_id, results);

    return true;
  } catch (err) {
    logger.error("[ModelHandler] Model search error:", err);
    await ctx.reply(t("model.search.error"));
    deps.interactionManager.clear("model_search_error");
    return true;
  }
}

/**
 * Handle callbacks from the search results menu:
 * - model:search:cancel — clears interaction, deletes message
 * - model:search:again — delegates to handleModelSearchCallback
 * - model:provider:model — selects the model from search results
 */
export async function handleModelSearchResults(
  ctx: Context,
  deps: ModelSelectionDeps,
): Promise<boolean> {
  const data = ctx.callbackQuery?.data;
  if (!data) {
    return false;
  }

  const meta = parseModelSearchMetadata(deps);
  if (!meta || meta.stage !== "results") {
    return false;
  }

  // Verify message ID matches to reject stale callbacks
  const callbackMessageId = ctx.callbackQuery?.message?.message_id;
  if (meta.messageId !== undefined && callbackMessageId !== meta.messageId) {
    await ctx
      .answerCallbackQuery({ text: t("inline.inactive_callback"), show_alert: true })
      .catch(() => {});
    return true;
  }

  // Cancel
  if (data === MODEL_SEARCH_CANCEL_CALLBACK) {
    deps.interactionManager.clear("model_search_cancelled");
    await cancelMenu(ctx);
    return true;
  }

  // Search again — inline implementation
  if (data === MODEL_SEARCH_AGAIN_CALLBACK) {
    await ctx.answerCallbackQuery().catch(() => {});
    await ctx.deleteMessage().catch(() => {});

    deps.interactionManager.start({
      kind: "custom",
      expectedInput: "text",
      metadata: {
        flow: "model-search",
        stage: "input",
      },
    });

    await ctx.reply(t("model.search.prompt"));

    logger.debug("[ModelHandler] Model search prompt shown (search again)");
    return true;
  }

  const resultIndex = parseCallbackIndex(data, MODEL_SEARCH_RESULT_CALLBACK_PREFIX);
  if (resultIndex !== null) {
    const modelInfo = meta.models[resultIndex];
    if (!modelInfo) {
      await ctx.answerCallbackQuery({ text: t("model.change_error_callback") }).catch(() => {});
      return true;
    }

    if (!(await isModelStillOffered(modelInfo))) {
      await redrawAfterStaleModelTap(ctx, () => showModelSearchResultsAgain(ctx, deps, meta));
      return true;
    }

    deps.interactionManager.clear("model_search_selected");
    await applyModelSelectionAndNotify(ctx, deps, modelInfo);
    return true;
  }

  // Backward compatibility for callbacks from already-rendered search result messages.
  if (data.startsWith("model:")) {
    if (isShortModelCallback(data)) {
      logger.error(`[ModelHandler] Invalid search result callback data: ${data}`);
      await ctx.answerCallbackQuery({ text: t("model.change_error_callback") }).catch(() => {});
      return true;
    }

    const modelInfo = parseLegacyModelCallback(data);
    if (!modelInfo) {
      return true;
    }

    if (!(await isModelStillOffered(modelInfo))) {
      await redrawAfterStaleModelTap(ctx, () => showModelSearchResultsAgain(ctx, deps, meta));
      return true;
    }

    deps.interactionManager.clear("model_search_selected");
    await applyModelSelectionAndNotify(ctx, deps, modelInfo);
    return true;
  }

  return false;
}

